def list_intersection(list1, list2):
    """Return the elements of list1 that also occur in list2, without repeats."""
    seen = set()
    common = []
    pool = set(list2)
    for item in list1:
        if item in pool and item not in seen:
            seen.add(item)
            common.append(item)
    return common


def list_union(list1, list2):
    """Return every distinct element of both lists, in first-seen order."""
    merged = []
    seen = set()
    for item in list(list1) + list(list2):
        if item not in seen:
            seen.add(item)
            merged.append(item)
    return merged


def jaccard_index(list1, list2):
    """Similarity of two lists: shared elements divided by all elements."""
    union = list_union(list1, list2)
    if not union:
        return 1.0
    return len(list_intersection(list1, list2)) / len(union)


def coverage(list1, list2):
    """Fraction of list1's distinct elements that are also present in list2."""
    distinct = list_union(list1, [])
    if not distinct:
        return 0.0
    return len(list_intersection(list1, list2)) / len(distinct)


def blended_score(list1, list2):
    """Average of the symmetric index and the two directional coverages."""
    directional = (coverage(list1, list2) + coverage(list2, list1)) / 2.0
    return (jaccard_index(list1, list2) + directional) / 2.0


def classify(score):
    if score >= 0.75:
        return "strong"
    if score >= 0.5:
        return "moderate"
    if score > 0.0:
        return "weak"
    return "disjoint"


def format_report(list1, list2):
    shared = list_intersection(list1, list2)
    score = blended_score(list1, list2)
    percent = score * 100.0
    shared_text = ", ".join(repr(item) for item in shared) if shared else "none"
    return "{} vs {} -> shared: {} | score {:.2f} ({:.1f}%) {}".format(
        list1, list2, shared_text, score, percent, classify(score)
    )


def main():
    cases = [
        ([1, 2, 3], [3, 4, 5]),
        ([1, 2], [3, 4]),
        (["a", "b", "b", "c"], ["c", "b"]),
        ([1, 2, 3, 4], [4, 3, 2, 1]),
        ([], []),
    ]
    for left, right in cases:
        print(format_report(left, right))
    best = max(cases, key=lambda pair: blended_score(*pair))
    print("closest pair:", best[0], "and", best[1])


if __name__ == "__main__":
    main()

