def merge_dictionaries(dict1, dict2):
    """Return a new dict with all pairs from both; dict2 wins on conflicts."""
    merged = dict(dict1)
    merged.update(dict2)
    return merged


def deep_merge(dict1, dict2):
    """Like merge_dictionaries, but nested dictionaries are merged recursively."""
    merged = dict(dict1)
    for key, value in dict2.items():
        current = merged.get(key)
        if isinstance(current, dict) and isinstance(value, dict):
            merged[key] = deep_merge(current, value)
        else:
            merged[key] = value
    return merged


def scale_numeric_values(mapping, factor=1.0):
    """Multiply every numeric leaf value by factor, leaving other values alone."""
    scaled = {}
    for key, value in mapping.items():
        if isinstance(value, dict):
            scaled[key] = scale_numeric_values(value, factor)
        elif isinstance(value, bool) or not isinstance(value, (int, float)):
            scaled[key] = value
        else:
            scaled[key] = value * factor
    return scaled


def clamp_ratios(mapping,
                 lower=0.0,
                 upper=1.0):
    """Keep float values inside [lower, upper]; useful for probabilities."""
    clamped = {}
    for key, value in mapping.items():
        if isinstance(value, float):
            clamped[key] = min(max(value, lower), upper)
        else:
            clamped[key] = value
    return clamped


def format_settings(mapping, indent=0):
    """Render a (possibly nested) settings dict as sorted, readable lines."""
    lines = []
    pad = " " * indent
    for key in sorted(mapping):
        value = mapping[key]
        if isinstance(value, dict):
            lines.append(f"{pad}{key}:")
            lines.extend(format_settings(value, indent + 2))
        elif isinstance(value, float):
            lines.append(f"{pad}{key} = {value:.3f}")
        else:
            lines.append(f"{pad}{key} = {value}")
    return lines


def main():
    print(merge_dictionaries({'a': 1, 'b': 2}, {'b': 3, 'c': 4}))

    defaults = {
        'learning_rate': 0.5,
        'momentum': 0.75,
        'epochs': 40,
        'dropout': {
            'input': 0.25,
            'hidden': 0.5,
        },
    }
    overrides = {
        'learning_rate': 2.25,
        'dropout': {'hidden': 1.5},
        'shuffle': True,
    }

    flat = merge_dictionaries(defaults, overrides)
    print("flat merge keys:", sorted(flat))

    config = deep_merge(defaults, overrides)
    config['dropout'] = clamp_ratios(config['dropout'], upper=0.75)
    print("\n".join(format_settings(config)))

    warmup = scale_numeric_values(config, 0.5)
    print("warm-up rate:", warmup['learning_rate'])


if __name__ == '__main__':
    main()

