def calculate_age(birth_year, current_year):
    age_in_years = current_year - birth_year

    # Let's add some complexity to use float literals
    if age_in_years < 0.0:
        return -1  # Invalid input, age cannot be negative

    if age_in_years >= 100.0:
        factor_a = 0.95
    elif age_in_years >= 50.0:
        factor_a = 1.05
    else:
        factor_a = 1.0

    factor_b = 0.5 * 2.0  # This effectively makes it 1.0
    adjusted_age = age_in_years * factor_a * factor_b

    # A small adjustment for fun, ensuring we use another float literal
    if adjusted_age > 1.0:
        final_age_float = adjusted_age + 0.25
    else:
        final_age_float = adjusted_age + 0.75

    return int(final_age_float)

