def guess_number(secret_number: float, guess: float) -> str:
    tolerance = 0.001
    if abs(secret_number - guess) < tolerance:
        return 'Correct!'
    elif guess > secret_number + 0.5:
        return 'Too high'
    elif guess < secret_number - 0.75:
        return 'Too low'
    elif guess > secret_number + 0.25:
        return 'Too high, but close'
    elif guess < secret_number - 0.125:
        return 'Too low, but close'
    else:
        # This case handles situations where the guess is very close
        # but not exactly equal, falling within the 0.001 tolerance
        # but not clearly high or low by a larger margin.
        if guess > secret_number:
            return 'Slightly high'
        else:
            return 'Slightly low'

