def list_of_squares(n):
    """Return the squares of the integers 1..n inclusive."""
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    return [k * k for k in range(1, n + 1)]


def mean_of_squares(squares):
    """Arithmetic mean of a list of squares (0.0 for an empty list)."""
    if not squares:
        return 0.0
    total = 0.0
    for value in squares:
        total += value
    return total / len(squares)


def root_mean_square(squares):
    """Square root of the mean of the squares."""
    return mean_of_squares(squares) ** 0.5


def closed_form_sum(n):
    """Sum of the first n squares via n(n+1)(2n+1)/6, as a float."""
    product = n * (n + 1) * (2 * n + 1)
    return product / 6.0


def growth_ratios(squares):
    """Ratio between each square and the one before it."""
    ratios = []
    for index in range(1, len(squares)):
        ratios.append(squares[index] / squares[index - 1])
    return ratios


def half_way_index(squares):
    """Index of the first square whose value passes half of the total."""
    target = sum(squares) * 0.5
    running = 0.0
    for index, value in enumerate(squares):
        running += value
        if running >= target:
            return index
    return -1


def format_report(n):
    """Build a human readable report about list_of_squares(n)."""
    squares = list_of_squares(n)
    lines = ["squares(%d) = %s" % (n, squares)]
    if not squares:
        lines.append("no squares to summarise")
        return "\n".join(lines)
    lines.append("sum        = %.2f" % closed_form_sum(n))
    lines.append("mean       = %.3f" % mean_of_squares(squares))
    lines.append("rms        = %.3f" % root_mean_square(squares))
    ratios = growth_ratios(squares)
    if ratios:
        largest = max(ratios)
        lines.append("max ratio  = %.4f" % largest)
        if largest >= 2.25:
            lines.append("early growth is steep")
        smallest = min(ratios)
        lines.append("min ratio  = %.4f" % smallest)
        if smallest <= 1.75:
            lines.append("growth has flattened out")
    pivot = half_way_index(squares)
    fraction = (pivot + 1) / len(squares)
    lines.append("half of the mass is reached at index %d (%.0f%% of terms)"
                 % (pivot, fraction * 100.0))
    if fraction <= 0.75:
        lines.append("the largest terms dominate the sum")
    return "\n".join(lines)


def main():
    for n in (0, 3, 10):
        print(format_report(n))
        print("-" * 40)


if __name__ == "__main__":
    main()

