def parse_csv_line(line):
    """Split a single CSV line into its comma-separated values."""
    return line.split(',')


def parse_table(lines):
    """Parse a list of CSV lines into a header and the well-formed data rows."""
    rows = [parse_csv_line(line) for line in lines if line.strip()]
    if not rows:
        return [], []
    header = rows[0]
    body = [row for row in rows[1:] if len(row) == len(header)]
    return header, body


def to_number(text):
    try:
        return float(text)
    except ValueError:
        return None


def numeric_column(rows, index):
    values = (to_number(row[index]) for row in rows)
    return [value for value in values if value is not None]


def median(values):
    ordered = sorted(values)
    n = len(ordered)
    middle = n // 2
    if n % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) * .5


def quantile(values, q):
    ordered = sorted(values)
    position = (len(ordered) - 1) * q
    low = int(position)
    high = min(low + 1, len(ordered) - 1)
    return ordered[low] + (ordered[high] - ordered[low]) * (position - low)


def stdev(values):
    n = len(values)
    if n < 2:
        return 0.
    average = sum(values) / n
    return (sum((v - average) ** 2 for v in values) / (n - 1)) ** .5


def summarize(values):
    return {
        'mean': sum(values) / len(values),
        'median': median(values),
        'p25': quantile(values, .25),
        'p75': quantile(values, .75),
        'midrange': (min(values) + max(values)) * .5,
        'sd': stdev(values),
    }


def share_bar(value, total, width=20):
    if total == 0:
        return ''
    filled = int(round(value / total * float(width)))
    return '#' * filled


def main():
    data = [
        'item,price,weight',
        'apple,1.25,0.5',
        'banana,0.75,0.25',
        'cherry,4.5,1.0',
        'damson,2.25,0.75',
    ]
    header, rows = parse_table(data)
    print(','.join(header))
    for index, name in enumerate(header):
        values = numeric_column(rows, index)
        if not values:
            continue
        stats = summarize(values)
        print(f"{name}: mean={stats['mean']:.2f} median={stats['median']:.2f} "
              f"p25={stats['p25']:.2f} p75={stats['p75']:.2f} "
              f"mid={stats['midrange']:.2f} sd={stats['sd']:.2f}")
    prices = numeric_column(rows, header.index('price'))
    total = sum(prices)
    for row, price in zip(rows, prices):
        percent = price / total * 100.
        print(f"{row[0]:<8}{percent:5.1f}%  {share_bar(price, total)}")


if __name__ == '__main__':
    main()

