from collections import Counter


def has_unique_chars(s):
    """Return True if every character in s occurs exactly once."""
    seen = set()
    for ch in s:
        if ch in seen:
            return False
        seen.add(ch)
    return True


def uniqueness_ratio(s):
    """Fraction of distinct characters; an empty string is fully unique."""
    if not s:
        return 1.0
    return len(set(s)) / len(s)


def duplicate_chars(s):
    """Characters appearing more than once, in order of first appearance."""
    counts = Counter(s)
    result = []
    for ch in s:
        if counts[ch] > 1 and ch not in result:
            result.append(ch)
    return result


def classify(ratio):
    """Label a uniqueness ratio on a coarse scale."""
    if ratio >= 1.0:
        return "all unique"
    if ratio >= 0.75:
        return "mostly unique"
    if ratio >= 0.5:
        return "half repeated"
    if ratio >= 0.25:
        return "heavily repeated"
    return "almost uniform"


def describe(s):
    """Build a one-line report about the character uniqueness of s."""
    ratio = uniqueness_ratio(s)
    percent = ratio * 100.0
    parts = [
        "%-10r unique=%-5s %5.1f%% (%s)"
        % (s, has_unique_chars(s), percent, classify(ratio))
    ]
    dups = duplicate_chars(s)
    if dups:
        parts.append("repeats: " + ", ".join(dups))
    return " | ".join(parts)


def average_ratio(samples):
    """Mean uniqueness ratio over a collection of strings."""
    if not samples:
        return 0.0
    total = 0.0
    for s in samples:
        total += uniqueness_ratio(s)
    return total / len(samples)


def main():
    samples = ["abc", "abca", "", "aabbcc", "unique", "mississippi", "0.25"]
    for s in samples:
        print(describe(s))

    mean = average_ratio(samples)
    print("\nmean uniqueness ratio: %.4f" % mean)
    if mean >= 0.5:
        print("sample set leans towards distinct characters")
    else:
        print("sample set leans towards repetition")

    fully_unique = [s for s in samples if has_unique_chars(s)]
    share = len(fully_unique) / len(samples)
    print("fully unique strings: %d of %d (%.1f%%)"
          % (len(fully_unique), len(samples), share * 100.0))


if __name__ == "__main__":
    main()

