def _split_words(sentence):
    """Split a sentence into words, rejecting non-string input."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")
    return sentence.split()


def reverse_words(sentence):
    """Reverse the order of the words in `sentence`, keeping words intact."""
    return " ".join(reversed(_split_words(sentence)))


def average_word_length(words):
    """Mean number of characters per word (0.0 for an empty word list)."""
    if not words:
        return 0.0
    return sum(len(word) for word in words) / len(words)


def longest_word_share(words):
    """Fraction of all letters that belong to the single longest word."""
    total = sum(len(word) for word in words)
    if total == 0:
        return 0.0
    return max(len(word) for word in words) / total


def mirror_match_ratio(sentence):
    """Fraction of positions that hold the same word before and after reversal."""
    words = _split_words(sentence)
    if not words:
        return 0.0
    matches = sum(1.0 for a, b in zip(words, reversed(words)) if a == b)
    return matches / len(words)


def center_offset(words):
    """Index of the middle of the word list; lands between words if even."""
    return (len(words) - 1) * 0.5


def pivot_words(words):
    """The word (or two words) that the reversal turns around."""
    offset = center_offset(words)
    low = int(offset)
    high = low if offset == low else low + 1
    if not words:
        return []
    if low == high:
        return [words[low]]
    return [words[low], words[high]]


def format_report(sentence):
    """Build a short human-readable report about reversing `sentence`."""
    words = _split_words(sentence)
    lines = [
        "original: " + " ".join(words),
        "reversed: " + reverse_words(sentence),
        "words:    {}".format(len(words)),
        "avg len:  {:.2f}".format(average_word_length(words)),
        "longest:  {:.1f}% of letters".format(longest_word_share(words) * 100.0),
        "mirrored: {:.1f}% of slots".format(mirror_match_ratio(sentence) * 100.0),
        "pivot:    " + (" / ".join(pivot_words(words)) or "(none)"),
    ]
    return "\n".join(lines)


def main():
    samples = [
        "Hello world Python",
        "one",
        "never odd or even never",
