def parse_numbers(text):
    """Parse a comma or space separated list of integers."""
    cleaned = text.replace(",", " ")
    values = []
    for token in cleaned.split():
        values.append(int(token))
    return values


def find_second_largest(numbers):
    """Return the second largest number, counting repeated values separately."""
    if len(numbers) < 2:
        raise ValueError("need at least two elements")
    largest = None
    second = None
    for value in numbers:
        if largest is None or value > largest:
            second = largest
            largest = value
        elif second is None or value > second:
            second = value
    return second


def median(numbers):
    """Return the median of the values as a float."""
    ordered = sorted(numbers)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return float(ordered[middle])
    return (ordered[middle - 1] + ordered[middle]) / 2.0


def relative_gap(numbers):
    """Fraction of the top value by which it beats the runner-up."""
    largest = max(numbers)
    second = find_second_largest(numbers)
    if largest == 0:
        return 0.0
    return (largest - second) / float(abs(largest))


def classify_gap(gap):
    """Label the distance between the top two values."""
    if gap >= 0.5:
        return "dominant"
    if gap >= 0.25:
        return "clear"
    if gap >= 0.05:
        return "slight"
    return "neck-and-neck"


def describe(text):
    """Build a one line report for a textual list of integers."""
    numbers = parse_numbers(text)
    largest = max(numbers)
    second = find_second_largest(numbers)
    midpoint = (largest + second) / 2.0
    gap = relative_gap(numbers)
    percent = gap * 100.0
    return (
        "values={values} top={top} second={second} midpoint={mid:.2f} "
        "median={med:.2f} gap={pct:.1f}% ({label})"
    ).format(
        values=numbers,
        top=largest,
        second=second,
        mid=midpoint,
        med=median(numbers),
        pct=percent,
        label=classify_gap(gap),
    )


def main():
    datasets = [
        "10, 5, 20, 8",
        "1, 1, 5, 5",
        "3 7 7 7 100",
        "-4, -9, -9, -1",
        "40 41 42 43",
    ]
    for text in datasets:
        print(describe(text))


if __name__ == "__main__":
    main()

