def run_length_encode(s):
    """Replace each run of identical characters by the character and its length."""
    if not s:
        return ''
    parts = []
    current = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            parts.append(current + str(count))
            current = ch
            count = 1
    parts.append(current + str(count))
    return ''.join(parts)


def run_length_decode(code):
    """Invert run_length_encode: 'A3B2C1' -> 'AAABBC'."""
    out = []
    index = 0
    while index < len(code):
        char = code[index]
        index += 1
        digits = ''
        while index < len(code) and code[index].isdigit():
            digits += code[index]
            index += 1
        if not digits:
            raise ValueError('missing run length for %r' % char)
        out.append(char * int(digits))
    return ''.join(out)


def compression_ratio(original, encoded):
    """Encoded length divided by original length; empty input compresses to 1.0."""
    if not original:
        return 1.0
    return len(encoded) / len(original)


def savings_percent(ratio):
    """Percentage of the original size removed by encoding; negative if it grew."""
    return (1.0 - ratio) * 100


def classify(ratio):
    if ratio <= 0.5:
        return 'excellent'
    if ratio <= 0.75:
        return 'good'
    if ratio < 1.0:
        return 'marginal'
    return 'expanded'


def describe(s):
    encoded = run_length_encode(s)
    if run_length_decode(encoded) != s:
        raise AssertionError('round trip failed for %r' % s)
    ratio = compression_ratio(s, encoded)
    return {
        'source': s,
        'encoded': encoded,
        'ratio': ratio,
        'saved': savings_percent(ratio),
        'verdict': classify(ratio),
    }


def main():
    samples = ['AAABBC', 'A', '', 'WWWWWWWWWWWWBWWWWWWWWWWWWBBB', 'abcdef', 'zz' * 16]
    total = 0.0
    for sample in samples:
        info = describe(sample)
        shown = info['source'] if len(info['source']) <= 20 else info['source'][:17] + '...'
        print('%-22s -> %-24s ratio %5.2f  saved %6.1f%%  %s' % (
            repr(shown), info['encoded'] or '(empty)', info['ratio'],
            info['saved'], info['verdict']))
        total += info['ratio']
    average = total / len(samples)
    print('average ratio: %.3f (%s)' % (average, classify(average)))
    if average > 1.0:
        print('encoding is a net loss on this sample set')


if __name__ == '__main__':
    main()

