STATUS_TEXT = {
    200: 'OK',
    404: 'Not Found',
    500: 'Internal Server Error',
}

FAST_LIMIT = 0.5
ACCEPTABLE_LIMIT = 1.0
SLOW_LIMIT = 2.25


def check_http_status(status_code):
    """Return a descriptive string for a handful of common HTTP status codes."""
    if isinstance(status_code, bool) or not isinstance(status_code, int):
        raise TypeError('status_code must be an integer')
    return STATUS_TEXT.get(status_code, 'Unknown Status')


def status_class(status_code):
    """Group a status code into its familiar 1xx..5xx family label."""
    if 100 <= status_code < 600:
        return '{0}xx'.format(status_code // 100)
    return 'invalid'


def latency_grade(seconds):
    """Describe how a single response time feels to a user."""
    if seconds < FAST_LIMIT:
        return 'fast'
    if seconds < ACCEPTABLE_LIMIT:
        return 'acceptable'
    if seconds < SLOW_LIMIT:
        return 'slow'
    return 'critical'


def percentile(values, fraction=0.75):
    """Linear-interpolation percentile of a list of numbers."""
    ordered = sorted(values)
    if not ordered:
        return 0.0
    position = (len(ordered) - 1) * fraction
    lower = int(position)
    upper = min(lower + 1, len(ordered) - 1)
    weight = position - lower
    return ordered[lower] * (1.0 - weight) + ordered[upper] * weight


def summarize(entries):
    """Build aggregate statistics for (status_code, seconds) log entries."""
    total = len(entries)
    latencies = [seconds for _code, seconds in entries]
    successes = sum(1 for code, _s in entries if status_class(code) == '2xx')
    families = {}
    for code, _seconds in entries:
        key = status_class(code)
        families[key] = families.get(key, 0) + 1
    divisor = float(total) or 1.0
    return {
        'total': total,
        'success_rate': successes / divisor,
        'mean_latency': sum(latencies) / divisor,
        'p75_latency': percentile(latencies),
        'families': families,
    }


def format_report(entries):
    """Render a per-request listing followed by the aggregate summary."""
    lines = []
    for code, seconds in entries:
        lines.append('{0:>3}  {1:<22} {2:5.2f}s  {3}'.format(
            code, check_http_status(code), seconds, latency_grade(seconds)))
    stats = summarize(entries)
    lines.append('requests: {0}'.format(stats['total']))
    lines.append('success rate: {0:.1f}%'.format(stats['success_rate'] * 100.0))
    lines.append('mean latency: {0:.3f}s ({1})'.format(
        stats['mean_latency'], latency_grade(stats['mean_latency'])))
    lines.append('p75 latency: {0:.3f}s'.format(stats['p75_latency']))
    for family in sorted(stats['families']):
        share = stats['families'][family] / (float(stats['total']) or 1.0)
        lines.append('  {0}: {1} ({2:.0%})'.format(
            family, stats['families'][family], share))
    if stats['p75_latency'] >= SLOW_LIMIT or stats['success_rate'] < 0.75:
        lines.append('VERDICT: service degraded')
    else:
        lines.append('VERDICT: service healthy')
    return '\n'.join(lines)


def main():
    log = [
        (200, 0.18),
        (200, 0.42),
        (404, 0.91),
        (200, 1.75),
        (500, 3.5),
        (401, 0.66),
    ]
    print(format_report(log))


if __name__ == '__main__':
    main()

