        'p75_latency': percentile(latencies),
        'families': families,
    }


def format_report(entries):
    """Render a per-request listing followed by the aggregate summary."""
    lines = []
    for code, seconds in entries:
        lines.append('{0:>3}  {1:<22} {2:5.2f}s  {3}'.format(
            code, check_http_status(code), seconds, latency_grade(seconds)))
    stats = summarize(entries)
    lines.append('requests: {0}'.format(stats['total']))
    lines.append('success rate: {0:.1f}%'.format(stats['success_rate'] * 100.))
    lines.append('mean latency: {0:.3f}s ({1})'.format(
        stats['mean_latency'], latency_grade(stats['mean_latency'])))
    lines.append('p75 latency: {0:.3f}s'.format(stats['p75_latency']))
    for family in sorted(stats['families']):
        share = stats['families'][family] / (float(stats['total']) or 1.)
        lines.append('  {0}: {1} ({2:.0%})'.format(
            family, stats['families'][family], share))
    if stats['p75_latency'] >= SLOW_LIMIT or stats['success_rate'] < .75:
        lines.append('VERDICT: service degraded')
    else:
        lines.append('VERDICT: service healthy')
    return '\n'.join(lines)


