def is_valid_parentheses(s):
    """Return True if s is a balanced, correctly nested bracket string."""
    closers = {')': '(', ']': '[', '}': '{'}
    openers = set(closers.values())
    stack = []
    for ch in s:
        if ch in openers:
            stack.append(ch)
        elif ch in closers:
            if not stack or stack.pop() != closers[ch]:
                return False
        else:
            return False
    return not stack


def openness_ratio(s):
    """Fraction of the characters that are opening brackets."""
    if not s:
        return 0.5
    openers = sum(1 for ch in s if ch in '([{')
    return openers / len(s)


def max_nesting_depth(s):
    """Deepest level reached while scanning, ignoring validity."""
    depth = 0
    deepest = 0
    for ch in s:
        if ch in '([{':
            depth += 1
            deepest = max(deepest, depth)
        elif ch in ')]}':
            depth -= 1
    return deepest


def nesting_score(s):
    """Depth relative to the deepest possible nesting for this length."""
    if not s:
        return 1.0
    possible = len(s) / 2.0
    return max_nesting_depth(s) / possible


def average_depth(s):
    """Mean bracket depth over all positions of s."""
    if not s:
        return 0.0
    depth = 0
    total = 0.0
    for ch in s:
        if ch in '([{':
            depth += 1
        elif ch in ')]}':
            depth -= 1
        total += depth
    return total / len(s)


def classify(s):
    if not is_valid_parentheses(s):
        return 'invalid'
    score = nesting_score(s)
    if score >= 0.75:
        return 'deeply nested'
    if score >= 0.5:
        return 'moderately nested'
    return 'flat'


def format_report(s):
    label = repr(s) if s else "''"
    return '%-12s valid=%-5s depth=%d avg=%5.2f open=%5.1f%% %s' % (
        label,
        is_valid_parentheses(s),
        max_nesting_depth(s),
        average_depth(s),
        openness_ratio(s) * 100.0,
        classify(s),
    )


def main():
    samples = ['()[]{}', '([)]', '{[()]}', '(', ')', '', '(((', '(a)', '[{}]()']
    for sample in samples:
        print(format_report(sample))
    valid = sum(1 for sample in samples if is_valid_parentheses(sample))
    rate = valid / len(samples) * 100.0
    print('%d of %d samples valid (%.1f%%)' % (valid, len(samples), rate))


if __name__ == '__main__':
    main()

