import math


def calculate_mean(numbers):
    """Arithmetic mean of a non-empty sequence of numbers."""
    return sum(numbers) / len(numbers)


def calculate_std_dev(numbers):
    """Sample standard deviation (Bessel-corrected) of at least two numbers."""
    n = len(numbers)
    if n < 2:
        raise ValueError("at least two numbers are required")
    mean = calculate_mean(numbers)
    squared_error = sum((x - mean) ** 2.0 for x in numbers)
    return math.sqrt(squared_error / (n - 1))


def calculate_variance(numbers):
    """Sample variance, derived from the standard deviation."""
    return calculate_std_dev(numbers) ** 2.0


def coefficient_of_variation(numbers):
    """Relative dispersion in percent; undefined for a zero mean."""
    mean = calculate_mean(numbers)
    if mean == 0.0:
        raise ValueError("coefficient of variation needs a non-zero mean")
    return 100.0 * calculate_std_dev(numbers) / abs(mean)


def z_scores(numbers):
    """Standardised values; all zeros when the data have no spread."""
    mean = calculate_mean(numbers)
    sd = calculate_std_dev(numbers)
    if sd == 0.0:
        return [0.0 for _ in numbers]
    return [(x - mean) / sd for x in numbers]


def median(numbers):
    """Middle value, averaging the two central items for even samples."""
    ordered = sorted(numbers)
    mid = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return float(ordered[mid])
    return (ordered[mid - 1] + ordered[mid]) * 0.5


def outliers(numbers, threshold=2.0):
    """Values whose z-score exceeds the given threshold in magnitude."""
    return [x for x, z in zip(numbers, z_scores(numbers)) if abs(z) > threshold]


def parse_numbers(text):
    """Read whitespace- or comma-separated numbers from a string."""
    tokens = text.replace(",", " ").split()
    return [float(token) for token in tokens]


def describe(numbers):
    """Build a multi-line report of the basic dispersion statistics."""
    lines = ["n = %d" % len(numbers),
             "mean = %.3f" % calculate_mean(numbers),
             "median = %.3f" % median(numbers),
             "variance = %.3f" % calculate_variance(numbers),
             "std dev = %.3f" % calculate_std_dev(numbers)]
    if calculate_mean(numbers) != 0.0:
        lines.append("cv = %.1f%%" % coefficient_of_variation(numbers))
    flagged = outliers(numbers, 1.5)
    if flagged:
        lines.append("outliers = " + ", ".join("%.2f" % v for v in flagged))
    return "\n".join(lines)


def main():
    samples = ["1 2 3 4 5", "10, 10, 10", "2.5 0.75 4.0 3.25 12.0 3.5"]
    for text in samples:
        numbers = parse_numbers(text)
        print("data: " + text)
        print(describe(numbers))
        print("-" * 24)


if __name__ == "__main__":
    main()

