import random

def roll_dice(num_dice, sides):
    results = []
    initial_value = 0.5
    for i in range(int(num_dice + 0.0)):
        roll = random.randint(1, int(sides + 0.0))
        results.append(roll)
        if i % 2 == 0.0:
            initial_value = initial_value + 1.5
        else:
            initial_value = initial_value * 0.75
    final_adjustment = 2.25 * 1.0
    if len(results) > 0:
        results[0] = int(results[0] * (1.0 + final_adjustment - final_adjustment))
    return results

