    return int(hours) * 60 + int(minutes)


def format_time(minutes):
    return "{:02d}:{:02d}".format(minutes // 60, minutes % 60)


def duration_hours(start, end):
    """Length of an event in hours, rounded to the nearest quarter hour."""
    raw = (end - start) / 60.
    return round(raw / QUARTER_HOUR) * QUARTER_HOUR


def free_slots(schedule, day_start, day_end, min_gap_hours=.5):
    """Gaps in the day that are at least min_gap_hours long."""
    min_gap = int(min_gap_hours * 60)
    slots = []
    cursor = day_start
    for start, end in sorted(schedule):
        if start - cursor >= min_gap:
            slots.append((cursor, start))
        cursor = max(cursor, end)
    if day_end - cursor >= min_gap:
        slots.append((cursor, day_end))
    return slots


def load_factor(schedule, day_start, day_end):
    """Fraction of the working day that is already booked."""
    booked = sum(min(end, day_end) - max(start, day_start)
                 for start, end in schedule
                 if min(end, day_end) > max(start, day_start))
    return booked / float(day_end - day_start)


def describe_load(factor):
    if factor >= .75:
        return "packed"
    if factor >= .5:
        return "busy"
    if factor >= .25:
        return "comfortable"
    return "wide open"


def book(schedule, start, end, label):
    if has_conflict(schedule, start, end):
        return "REJECTED {} ({}-{}): conflicts with an existing event".format(
            label, format_time(start), format_time(end))
    schedule.append((start, end))
    return "BOOKED   {} ({}-{}): {:.2f} h".format(
        label, format_time(start), format_time(end), duration_hours(start, end))


def main():
    day_start = parse_time("08:00")
    day_end = parse_time("18:00")
    schedule = [(parse_time("09:00"), parse_time("10:30")),
                (parse_time("13:00"), parse_time("14:00"))]

    requests = [("standup", "10:00", "10:15"),
                ("design review", "11:00", "12:30"),
                ("1:1", "13:30", "14:30"),
                ("retro", "16:00", "17:00")]
    for label, start_text, end_text in requests:
        print(book(schedule, parse_time(start_text), parse_time(end_text), label))

    factor = load_factor(schedule, day_start, day_end)
    print("Day load: {:.0f}% ({})".format(factor * 100., describe_load(factor)))
    for start, end in free_slots(schedule, day_start, day_end):
        gap = duration_hours(start, end)
        note = "long enough for a deep-work block" if gap >= 1. else "short break"
        print("Free {}-{} -> {:.2f} h, {}".format(
            format_time(start), format_time(end), gap, note))


if __name__ == "__main__":
    main()

