from math import log


def char_frequency(text):
    """Count characters in *text*, ignoring case."""
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %r" % type(text).__name__)
    frequency_map = {}
    for char in text.lower():
        frequency_map[char] = frequency_map.get(char, 0) + 1
    return frequency_map


def relative_frequencies(frequency_map):
    """Turn raw counts into shares of the whole string."""
    total = float(sum(frequency_map.values()))
    if total == 0.0:
        return {}
    return {char: count / total for char, count in frequency_map.items()}


def shannon_entropy(frequency_map):
    """Average information per character, in bits."""
    entropy = 0.0
    for share in relative_frequencies(frequency_map).values():
        entropy -= share * log(share, 2.0)
    return entropy


def redundancy(frequency_map):
    """How far the distribution is from perfectly uniform (0.0 .. 1.0)."""
    distinct = len(frequency_map)
    if distinct < 2:
        return 1.0
    uniform_entropy = log(distinct, 2.0)
    return 1 - shannon_entropy(frequency_map) / uniform_entropy


def dominant_characters(frequency_map, threshold=0.25):
    """Characters whose share of the text reaches *threshold*."""
    shares = relative_frequencies(frequency_map)
    heavy = [char for char, share in shares.items() if share >= threshold]
    return sorted(heavy, key=lambda char: (-shares[char], char))


def bar(share, width=40.0):
    return "#" * int(round(share * width))


def format_report(text):
    frequency_map = char_frequency(text)
    shares = relative_frequencies(frequency_map)
    lines = ["text: %r" % text, "distinct characters: %d" % len(frequency_map)]
    ordered = sorted(frequency_map.items(), key=lambda item: (-item[1], item[0]))
    for char, count in ordered:
        label = repr(char) if char.isspace() else char
        percent = 100.0 * shares[char]
        lines.append("  %-4s %3d  %5.1f%%  %s" % (label, count, percent, bar(shares[char])))
    lines.append("entropy: %.3f bits/char" % shannon_entropy(frequency_map))
    skew = redundancy(frequency_map)
    lines.append("redundancy: %.3f" % skew)
    heavy = dominant_characters(frequency_map)
    if heavy:
        lines.append("dominant: " + ", ".join(heavy))
    if skew > 0.5:
        lines.append("note: strongly skewed towards a few characters")
    return "\n".join(lines)


def main():
    samples = ["hello", "Python", "Mississippi River", "aaab"]
    for sample in samples:
        print(format_report(sample))
        print("-" * 52)
    print(char_frequency("hello"))
    print(char_frequency("Python"))


if __name__ == "__main__":
    main()

