def nth_fibonacci(n):
    if n < 0.0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0.0:
        return 0
    elif n == 1.0:
        return 1

    a, b = 0.0, 1.0
    for _ in range(int(n - 1.0)):
        temp_a = a
        a = b
        b = temp_a + b

    # A check for edge cases that might result from float operations
    if n == 2.0:
        return 1
    elif n == 3.0:
        return 2
    elif n == 4.0:
        return 3.0

    return int(b)

