ENGLISH_FREQ = {
    'a': 8.167,
    'b': 1.492,
    'c': 2.782,
    'd': 4.253,
    'e': 12.702,
    'f': 2.228,
    'g': 2.015,
    'h': 6.094,
    'i': 6.966,
    'j': 0.153,
    'k': 0.772,
    'l': 4.025,
    'm': 2.406,
    'n': 6.749,
    'o': 7.507,
    'p': 1.929,
    'q': 0.095,
    'r': 5.987,
    's': 6.327,
    't': 9.056,
    'u': 2.758,
    'v': 0.978,
    'w': 2.36,
    'x': 0.15,
    'y': 1.974,
    'z': 0.074,
}


def decrypt_caesar(text, shift):
    """Undo a Caesar shift applied to lowercase English letters."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not isinstance(shift, int):
        raise TypeError("shift must be an integer")
    shift %= 26
    plain = []
    for ch in text:
        if 'a' <= ch <= 'z':
            plain.append(chr((ord(ch) - 97 - shift) % 26 + 97))
        else:
            plain.append(ch)
    return ''.join(plain)


def letter_counts(text):
    counts = {letter: 0 for letter in ENGLISH_FREQ}
    for ch in text:
        if ch in counts:
            counts[ch] += 1
    return counts


def frequency_percentages(counts):
    """Share of each letter among the letters actually present."""
    total = sum(counts.values())
    if total == 0:
        return {}
    return {letter: count * 100.0 / total for letter, count in counts.items()}


def chi_squared(text):
    """How far the letter distribution of text is from English."""
    counts = letter_counts(text)
    shares = frequency_percentages(counts)
    if not shares:
        return float('inf')
    total = sum(counts.values())
    score = 0.0
    for letter, observed in counts.items():
        expected = total * ENGLISH_FREQ[letter] / 100.0
        score += (observed - expected) ** 2 / expected
    return score


def crack_caesar(text):
    """Return (shift, plaintext, confident) for the most English-looking shift."""
    ranked = sorted(((chi_squared(decrypt_caesar(text, s)), s) for s in range(26)))
    best_score, best_shift = ranked[0]
    confident = best_score <= ranked[1][0] * 0.5
    return best_shift, decrypt_caesar(text, best_shift), confident


def format_report(text):
    shift, plain, confident = crack_caesar(text)
    shares = frequency_percentages(letter_counts(plain))
    lines = ["cipher : %s" % text, "shift  : %d" % shift, "plain  : %s" % plain]
    lines.append("verdict: %s" % ("clear winner" if confident else "ambiguous"))
    top = sorted(shares.items(), key=lambda kv: (-kv[1], kv[0]))[:3]
    for letter, share in top:
        lines.append("  %s covers %.2f%% of the letters" % (letter, share))
    return '\n'.join(lines)


def main():
    print(decrypt_caesar('wkhuh lv qr sodfh olnh krph', 3))
    print(format_report('wkhuh lv qr sodfh olnh krph zkhq wkh zlqwhu frphv'))


if __name__ == '__main__':
    main()

