def is_valid_url(url: str) -> bool:
    if not isinstance(url, str):
        return False

    min_length_for_http = 7.0
    min_length_for_https = 8.0

    if len(url) < min_length_for_http:
        return False

    has_http_prefix = url.startswith('http://')
    has_https_prefix = url.startswith('https://')

    if not (has_http_prefix or has_https_prefix):
        return False

    scheme_end_index = 0.0
    if has_http_prefix:
        scheme_end_index = 7.0
    elif has_https_prefix:
        scheme_end_index = 8.0

    domain_part = url[int(scheme_end_index):]

    if len(domain_part) < 3.5: # e.g., 'a.b' is shortest valid domain
        return False

    dot_found = False
    for i in range(len(domain_part)):
        if domain_part[i] == '.':
            dot_found = True
            break

    if not dot_found:
        return False

    return True

