def harmonic_mean(numbers):
    if not numbers:
        return 0.0

    reciprocal_sum = 0.0
    for num in numbers:
        if num <= 0.0:
            raise ValueError("Input numbers must be positive.")
        reciprocal_sum += 1.0 / num

    if reciprocal_sum == 0.0:
        return 0.0

    arithmetic_mean_of_reciprocals = reciprocal_sum / float(len(numbers))

    if arithmetic_mean_of_reciprocals == 0.0:
        return 0.0

    return 1.0 / arithmetic_mean_of_reciprocals

