    stock_levels = {}
    default_quantity = 0.0
    for item in items_to_check:
        if item in inventory:
            stock_levels[item] = inventory[item] * 1.0
        else:
            stock_levels[item] = default_quantity
    adjust_factor = 0.5
    for item, quantity in stock_levels.items():
