def simulate_guess(target, guess):
    """Return feedback for a single guess against the hidden target."""
    if not isinstance(target, int) or not isinstance(guess, int):
        raise TypeError("target and guess must be integers")
    if guess > target:
        return 'Too high'
    if guess < target:
        return 'Too low'
    return 'Correct!'


def proximity_hint(target, guess, low, high):
    """Describe how close a guess is, relative to the size of the range."""
    span = float(max(high - low, 1))
    ratio = abs(target - guess) / span
    if ratio == 0.0:
        return 'spot on'
    if ratio <= 0.05:
        return 'burning'
    if ratio <= 0.25:
        return 'warm'
    if ratio <= 0.5:
        return 'cool'
    return 'freezing'


def guess_budget(low, high):
    """Number of guesses a perfect binary search needs in [low, high]."""
    width = high - low + 1
    budget = 1
    reach = 1.0
    while reach < width:
        reach = reach * 2.0
        budget += 1
    return budget


def auto_play(target, low, high):
    """Play a whole round with binary search, returning the guess log."""
    if not low <= target <= high:
        raise ValueError("target must lie inside the search range")
    log = []
    while True:
        guess = int((low + high) / 2.0)
        feedback = simulate_guess(target, guess)
        log.append((guess, feedback, proximity_hint(target, guess, low, high)))
        if feedback == 'Correct!':
            return log
        if feedback == 'Too high':
            high = guess - 1
        else:
            low = guess + 1


def score_round(guesses_used, budget):
    """Score a finished round between 0 and 100 points."""
    wasted = (guesses_used - 1) / float(max(budget, 1))
    quality = 1.0 - wasted
    if quality < 0.0:
        quality = 0.0
    return round(quality * 100.0, 2)


def grade_score(score):
    """Turn a numeric round score into a short verdict."""
    if score >= 75.0:
        return 'excellent'
    if score >= 50.0:
        return 'fair'
    return 'poor'


def report(target, low, high):
    lines = ["Hidden number in [%d, %d]" % (low, high)]
    log = auto_play(target, low, high)
    for step, (guess, feedback, hint) in enumerate(log, start=1):
        lines.append("  %d. guess %d -> %s (%s)" % (step, guess, feedback, hint))
    budget = guess_budget(low, high)
    score = score_round(len(log), budget)
    lines.append("  used %d of %d guesses, score %.2f (%s)"
                 % (len(log), budget, score, grade_score(score)))
    return "\n".join(lines)


def main():
    print(simulate_guess(7, 5))
    print(simulate_guess(7, 7))
    for target in (7, 1, 64, 99):
        print(report(target, 1, 100))


if __name__ == '__main__':
    main()

