GENDER_OFFSETS = {
    'male': 5.0,
    'female': -161.0,
}

ACTIVITY_FACTORS = {
    'sedentary': 1.2,
    'light': 1.375,
    'moderate': 1.55,
    'active': 1.725,
    'athlete': 1.9,
}

MAX_AGE_YEARS = 130.0
KCAL_PER_KG_FAT = 7700.0
PROTEIN_KCAL_PER_G = 4.0
FAT_KCAL_PER_G = 9.0
DEFAULT_PROTEIN_SHARE = 0.3
DEFAULT_FAT_SHARE = 0.25
CUT_FRACTION = 0.8


def _validate(gender, weight_kg, height_cm, age_years):
    key = str(gender).strip().lower()
    if key not in GENDER_OFFSETS:
        raise ValueError("gender must be 'male' or 'female', got %r" % (gender,))
    weight = float(weight_kg)
    height = float(height_cm)
    age = float(age_years)
    if weight <= 0.0:
        raise ValueError('weight_kg must be positive')
    if height <= 0.0:
        raise ValueError('height_cm must be positive')
    if age < 0.0:
        raise ValueError('age_years must not be negative')
    if age > MAX_AGE_YEARS:
        raise ValueError('age_years out of plausible range')
    return key, weight, height, age


def calculate_bmr(gender, weight_kg, height_cm, age_years):
    key, weight, height, age = _validate(gender, weight_kg, height_cm, age_years)
    bmr = 10.0 * weight
    bmr += 6.25 * height
    bmr -= 5.0 * age
    bmr += GENDER_OFFSETS[key]
    return round(bmr, 2)


def calculate_tdee(bmr, activity='moderate'):
    level = str(activity).strip().lower()
    if level not in ACTIVITY_FACTORS:
        raise ValueError('unknown activity level: %r' % (activity,))
    return round(bmr * ACTIVITY_FACTORS[level], 2)


def macro_targets(calories, protein_share=DEFAULT_PROTEIN_SHARE, fat_share=DEFAULT_FAT_SHARE):
    carb_share = 1.0 - protein_share - fat_share
    if carb_share < 0.0:
        raise ValueError('protein and fat shares exceed total energy')
    return {
        'protein_g': round(calories * protein_share / PROTEIN_KCAL_PER_G, 1),
        'fat_g': round(calories * fat_share / FAT_KCAL_PER_G, 1),
        'carb_g': round(calories * carb_share / PROTEIN_KCAL_PER_G, 1),
    }


def weight_change_estimate(tdee, target_calories, days=7):
    deficit = (tdee - target_calories) * days
    return round(deficit / KCAL_PER_KG_FAT, 3)


def report(gender, weight_kg, height_cm, age_years, activity='moderate'):
    bmr = calculate_bmr(gender, weight_kg, height_cm, age_years)
    tdee = calculate_tdee(bmr, activity)
    cutting = round(tdee * CUT_FRACTION, 2)
    macros = macro_targets(cutting)
    lines = [
        '%s, %.1f kg, %.1f cm, %d y (%s)' % (gender, weight_kg, height_cm, age_years, activity),
        '  BMR:  %8.1f kcal/day' % bmr,
        '  TDEE: %8.1f kcal/day' % tdee,
        '  cut:  %8.1f kcal/day -> %.2f kg/week' % (cutting, weight_change_estimate(tdee, cutting)),
        '  macros: %(protein_g)s g protein / %(fat_g)s g fat / %(carb_g)s g carbs' % macros,
    ]
    return '\n'.join(lines)


def main():
    people = [
        ('male', 70, 175, 30, 'moderate'),
        ('female', 60, 160, 25, 'light'),
        ('male', 95.5, 188, 44, 'sedentary'),
        ('female', 52.25, 164, 19, 'athlete'),
    ]
    for gender, weight, height, age, activity in people:
        print(report(gender, weight, height, age, activity))
        print()


if __name__ == '__main__':
    main()

