def cubes_up_to(limit):
    """Return the cubes of 0..limit inclusive, built with a list comprehension."""
    if not isinstance(limit, int):
        raise TypeError("limit must be an int")
    if limit < 0:
        raise ValueError("limit must be non-negative")
    cubes_list = [n ** 3 for n in range(limit + 1)]
    return cubes_list


def mean_of(values):
    """Arithmetic mean of a non-empty sequence of numbers."""
    if not values:
        raise ValueError("mean of an empty sequence is undefined")
    return sum(values) / float(len(values))


def median_of(values):
    """Median of a non-empty sequence of numbers."""
    if not values:
        raise ValueError("median of an empty sequence is undefined")
    ordered = sorted(values)
    mid = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return float(ordered[mid])
    return (ordered[mid - 1] + ordered[mid]) * 0.5


def growth_ratios(cubes):
    """Ratio between each cube and the previous one, skipping division by zero."""
    return [cubes[i] / float(cubes[i - 1])
            for i in range(1, len(cubes)) if cubes[i - 1] != 0]


def cube_root(value, tolerance=0.000001):
    """Newton's method for the real cube root of a non-negative number."""
    if value <= 0:
        return 0.0
    guess = max(float(value), 1.0)
    while True:
        better = (guess + guess + value / (guess * guess)) / 3.0
        if abs(better - guess) <= tolerance * max(guess, 1.0):
            return better
        guess = better


def shares(cubes):
    """Percentage contribution of every cube to the total."""
    total = sum(cubes)
    if total == 0:
        return [0.0 for _c in cubes]
    return [100.0 * c / total for c in cubes]


def report(limit):
    """Human readable summary of the cubes produced for a given limit."""
    cubes = cubes_up_to(limit)
    lines = ["limit %d -> %s" % (limit, cubes)]
    lines.append("  mean   %.2f" % mean_of(cubes))
    lines.append("  median %.2f" % median_of(cubes))
    ratios = growth_ratios(cubes)
    if ratios:
        lines.append("  last growth ratio %.3f" % ratios[-1])
        lines.append("  average growth    %.3f" % mean_of(ratios))
    largest = cubes[-1]
    approx = cube_root(largest)
    nearest = int(approx + 0.5)
    lines.append("  cube root of %d is %.4f (nearest %d)" % (largest, approx, nearest))
    lines.append("  largest share %.1f%% of the total" % max(shares(cubes)))
    return "\n".join(lines)


def main():
    for limit in (3, 0, 1, 10):
        print(report(limit))
        print("")


if __name__ == "__main__":
    main()

