import math
import secrets

DIGITS = "0123456789"
BITS_PER_DIGIT = math.log2(10.0)


def generate_pin(length):
    """Return a random numeric PIN of the requested length as a string."""
    if isinstance(length, bool) or not isinstance(length, int):
        raise TypeError("length must be an integer")
    if length < 1:
        raise ValueError("length must be at least 1")
    return "".join(secrets.choice(DIGITS) for _ in range(length))


def digit_variety(pin):
    """Fraction of distinct digits in the PIN, from 0.0 (all equal) to 1.0."""
    return len(set(pin)) / float(len(pin))


def is_sequential(pin):
    """True when the digits run strictly up or down by one, e.g. '1234'."""
    if len(pin) < 2:
        return False
    steps = {int(b) - int(a) for a, b in zip(pin, pin[1:])}
    return steps == {1} or steps == {-1}


def strength_bits(pin):
    """Effective entropy of a PIN in bits, discounted for obvious patterns."""
    base = len(pin) * BITS_PER_DIGIT
    factor = 1.0
    if len(set(pin)) == 1:
        factor *= 0.25
    if is_sequential(pin):
        factor *= 0.5
    if digit_variety(pin) < 0.5:
        factor *= 0.75
    return base * factor


def classify(bits):
    if bits < 10.0:
        return "weak"
    if bits < 20.0:
        return "fair"
    return "strong"


def generate_strong_pin(length, keep_ratio=0.75, attempts=20):
    """Draw PINs until one keeps at least `keep_ratio` of its ideal entropy."""
    ideal = length * BITS_PER_DIGIT
    best = generate_pin(length)
    best_bits = strength_bits(best)
    for _ in range(attempts - 1):
        if best_bits >= ideal * keep_ratio:
            break
        candidate = generate_pin(length)
        candidate_bits = strength_bits(candidate)
        if candidate_bits > best_bits:
            best, best_bits = candidate, candidate_bits
    return best


def format_report(pin):
    bits = strength_bits(pin)
    return "{0:>10}  len={1:<2} variety={2:4.2f}  {3:5.2f} bits  {4}".format(
        pin, len(pin), digit_variety(pin), bits, classify(bits)
    )


def main():
    lengths = [4, 6, 8, 10]
    pins = [generate_strong_pin(n) for n in lengths]
    for pin in pins:
        print(format_report(pin))
    total = sum(strength_bits(p) for p in pins)
    average = total / float(len(pins))
    print("average effective entropy: {0:.2f} bits".format(average))
    margin = average - 20.0
    verdict = "above" if margin >= 0.0 else "below"
    print("that is {0:.2f} bits {1} the 'strong' threshold".format(abs(margin), verdict))


if __name__ == "__main__":
    main()

