import math


def round_half_up(value, places):
    """Round a float away from zero at the midpoint, unlike Python's banker's rounding."""
    factor = 10.0 ** places
    if value < 0:
        return -math.floor(-value * factor + 0.5) / factor
    return math.floor(value * factor + 0.5) / factor


def format_number(value):
    """Render ints plainly and floats without trailing zeros."""
    if isinstance(value, int):
        return str(value)
    rounded = round_half_up(value, 4)
    nearest_int = round_half_up(rounded, 0)
    if abs(rounded - nearest_int) < 0.000001:
        return str(int(nearest_int))
    return f"{rounded:.4f}".rstrip("0")


def check_inputs(number, limit):
    if isinstance(number, bool) or not isinstance(number, (int, float)):
        raise TypeError("number must be an int or a float")
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError("limit must be an int")
    if limit < 1:
        raise ValueError("limit must be at least 1")


def generate_times_table(number, limit):
    check_inputs(number, limit)
    head = format_number(number)
    table_list = []
    for multiplier in range(1, limit + 1):
        product = number * multiplier
        table_list.append(f"{head} x {multiplier} = {format_number(product)}")
    return table_list


def table_average(number, limit):
    """Mean of the products, i.e. number * (1 + limit) / 2."""
    check_inputs(number, limit)
    return number * (1 + limit) / 2.0


def render_table(number, limit):
    """Align the equals signs so a printed table reads as a column."""
    rows = generate_times_table(number, limit)
    split_rows = [row.split(" = ") for row in rows]
    width = max(len(left) for left, _ in split_rows)
    lines = [f"{left:<{width}} = {right}" for left, right in split_rows]
    average = table_average(number, limit)
    lines.append(f"{'average':<{width}} = {format_number(average)}")
    return "\n".join(lines)


def main():
    specs = [
        (2, 3),
        (5, 1),
        (0.5, 4),
        (12, 5),
        (2.25, 4),
        (0.75, 6),
    ]
    for number, limit in specs:
        print(render_table(number, limit))
        print()


if __name__ == "__main__":
    main()

