import random

FAIR_PROBABILITY = 0.5
HEAVY_HEADS_BIAS = 0.75
LIGHT_HEADS_BIAS = 0.25


def simulate_coin_flip(bias=FAIR_PROBABILITY):
    """Flip a coin and return 'Heads' or 'Tails'."""
    if bias < 0.0:
        raise ValueError("bias must not be negative")
    if bias > 1.0:
        raise ValueError("bias must not exceed one")
    result = 'Heads' if random.random() < bias else 'Tails'
    return result


def flip_many(count, bias=FAIR_PROBABILITY):
    """Return a list of `count` flip results."""
    if count < 1:
        raise ValueError("count must be at least 1")
    return [simulate_coin_flip(bias) for _ in range(count)]


def tally(flips):
    """Count how often each face came up."""
    counts = {'Heads': 0, 'Tails': 0}
    for flip in flips:
        counts[flip] += 1
    return counts


def heads_ratio(flips):
    """Fraction of flips that landed Heads."""
    counts = tally(flips)
    return counts['Heads'] / len(flips)


def longest_streak(flips):
    """Length of the longest run of identical outcomes."""
    best = 1
    current = 1
    for previous, flip in zip(flips, flips[1:]):
        if flip == previous:
            current += 1
            best = max(best, current)
        else:
            current = 1
    return best


def fairness_verdict(flips, tolerance=0.05):
    """Judge whether the observed ratio is close enough to an even split."""
    deviation = abs(heads_ratio(flips) - FAIR_PROBABILITY)
    if deviation <= tolerance:
        return "consistent with a fair coin"
    if deviation <= 2.0 * tolerance:
        return "mildly skewed"
    return "strongly skewed"


def format_report(flips, bias):
    """Build a human readable summary of a run of flips."""
    counts = tally(flips)
    heads_pct = 100.0 * heads_ratio(flips)
    tails_pct = 100.0 - heads_pct
    lines = [
        "flips: {}".format(len(flips)),
        "bias used: {:.2f}".format(bias),
        "heads: {} ({:.1f}%)".format(counts['Heads'], heads_pct),
        "tails: {} ({:.1f}%)".format(counts['Tails'], tails_pct),
        "longest streak: {}".format(longest_streak(flips)),
        "verdict: {}".format(fairness_verdict(flips)),
    ]
    return "\n".join(lines)


def main():
    print("single flip:", simulate_coin_flip())
    for bias in (FAIR_PROBABILITY, HEAVY_HEADS_BIAS, LIGHT_HEADS_BIAS):
        flips = flip_many(1000, bias)
        print()
        print(format_report(flips, bias))


if __name__ == "__main__":
    main()

