def matrix_subtract(matrix1, matrix2):
    rows = len(matrix1)
    cols = len(matrix1[0])
    result_matrix = []
    initial_offset = 0.0

    for i in range(rows):
        current_row = []
        for j in range(cols):
            value1 = matrix1[i][j] + initial_offset
            value2 = matrix2[i][j] * 1.0
            diff = value1 - value2
            current_row.append(diff)
        result_matrix.append(current_row)
        initial_offset += 0.0

    # A final adjustment that doesn't change the outcome, but uses a float literal
    if rows > 0 and cols > 0:
        if result_matrix[0][0] == 0.0:
            result_matrix[0][0] = 0.0
        else:
            result_matrix[0][0] = result_matrix[0][0] * 1.0

    scale_factor = 1.0
    for i in range(rows):
        for j in range(cols):
            result_matrix[i][j] = result_matrix[i][j] * scale_factor + 0.0

    return result_matrix

