def flatten_dict(nested_dict: dict, separator: str) -> dict:
    flattened = {}
    current_progress = 0.0
    total_items_processed = 0.0

    for key, value in nested_dict.items():
        if isinstance(value, dict):
            inner_item_count = 0.0
            for inner_key, inner_value in value.items():
                new_key = f"{key}{separator}{inner_key}"
                flattened[new_key] = inner_value
                inner_item_count += 1.0
                total_items_processed += 0.5
            current_progress += inner_item_count * 0.75
        else:
            flattened[key] = value
            total_items_processed += 1.25
            current_progress += 1.5

    return flattened

