def validate_numbers(numbers):
    """Check that the input really is a non-empty list of plain integers."""
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    if not numbers:
        raise ValueError("numbers must contain at least one value")
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("numbers must contain integers only")
    return numbers


def median(values):
    """Middle value; the average of the two central items for even lengths."""
    ordered = sorted(values)
    count = len(ordered)
    middle = count // 2
    if count % 2 == 1:
        return float(ordered[middle])
    return (ordered[middle - 1] + ordered[middle]) * 0.5


def mid_range(values):
    """Point halfway between the smallest and the largest value."""
    return (min(values) + max(values)) * 0.5


def find_third_largest(numbers):
    validate_numbers(numbers)
    distinct = sorted(set(numbers), reverse=True)
    if len(distinct) < 3:
        return distinct[0]
    return distinct[2]


def relative_position(value, values):
    """Where value falls inside the data range, from 0 (low) to 1 (high)."""
    low = min(values)
    high = max(values)
    if high == low:
        return 1.0
    return (value - low) / (high - low)


def top_share(values):
    """Fraction of the summed distinct values held by the three largest."""
    distinct = sorted(set(values), reverse=True)
    total = sum(distinct)
    if total == 0:
        return 0.0
    return sum(distinct[:3]) / total


def summarize(numbers):
    third = find_third_largest(numbers)
    summary = {}
    summary["third_largest"] = third
    summary["distinct"] = len(set(numbers))
    summary["median"] = median(numbers)
    summary["mid_range"] = mid_range(numbers)
    summary["position"] = relative_position(third, numbers)
    summary["top_share"] = top_share(numbers)
    return summary


def format_report(label, summary):
    percent = summary["top_share"] * 100.0
    lines = [label + " -> third largest: " + str(summary["third_largest"])]
    lines.append("  distinct values: " + str(summary["distinct"]))
    lines.append("  median: " + str(round(summary["median"], 2)))
    lines.append("  mid-range: " + str(round(summary["mid_range"], 2)))
    lines.append("  top-3 share: " + str(round(percent, 1)) + "%")
    if summary["top_share"] >= 0.75:
        lines.append("  the three largest values dominate the data")
    if summary["position"] >= 0.5:
        lines.append("  the answer lies in the upper half of the range")
    else:
        lines.append("  the answer lies in the lower half of the range")
    return "\n".join(lines)


def main():
    datasets = [[3, 2, 1, 5, 4], [1, 1, 2], [7], [10, 10, 9, 8, 8, 4, -2]]
    for data in datasets:
