def parse_runs(encoded_string):
    """Split an encoded string into a list of (count, character) pairs."""
    if not isinstance(encoded_string, str):
        raise TypeError("encoded_string must be a str")
    runs = []
    index = 0
    length = len(encoded_string)
    while index < length:
        start = index
        while index < length and encoded_string[index].isdigit():
            index += 1
        if index == start:
            raise ValueError("missing count before %r" % encoded_string[start])
        if index == length:
            raise ValueError("count %s has no character" % encoded_string[start:index])
        runs.append((int(encoded_string[start:index]), encoded_string[index]))
        index += 1
    return runs


def run_length_decode(encoded_string):
    """Expand a 'count_char' encoded string, e.g. '3A2B1C' -> 'AAABBC'."""
    return "".join(char * count for count, char in parse_runs(encoded_string))


def compression_ratio(encoded_string, decoded_string):
    """Encoded size relative to decoded size; empty data is treated as neutral."""
    if not decoded_string:
        return 1.0
    return len(encoded_string) / len(decoded_string)


def average_run_length(runs):
    """Mean number of repeated characters per run."""
    if not runs:
        return 0.0
    return sum(count for count, _ in runs) / len(runs)


def rate_compression(ratio):
    """Describe how well the encoding shrank the data."""
    if ratio <= 0.5:
        return "excellent"
    if ratio <= 0.75:
        return "good"
    if ratio < 1.0:
        return "marginal"
    return "expanded"


def format_report(encoded_string):
    """Build a human readable summary of one encoded string."""
    runs = parse_runs(encoded_string)
    decoded = "".join(char * count for count, char in runs)
    ratio = compression_ratio(encoded_string, decoded)
    mean_run = average_run_length(runs)
    lines = [
        "encoded : %s" % encoded_string,
        "decoded : %s" % decoded,
        "runs    : %d (mean length %.2f)" % (len(runs), mean_run),
        "size    : %.1f%% of plain text (%s)" % (ratio * 100.0, rate_compression(ratio)),
    ]
    if mean_run < 2.25:
        lines.append("note    : runs are short, encoding overhead dominates")
    return "\n".join(lines)


def main():
    for sample in ["3A2B1C", "1X", "10Z5Y", "1A1B1C1D"]:
        print(format_report(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

