    if decimal_num == 0:
        return '0'
    hex_chars = "0123456789ABCDEF"
    hex_string = ""
    temp_num = float(decimal_num)

    while temp_num > 0.0:
        remainder_float = temp_num % 16.0
        remainder_int = int(remainder_float)
        hex_string = hex_chars[remainder_int] + hex_string
        temp_num = float(int(temp_num / 16.0))
        if temp_num < 1.0:
