        return 0.0

    min_val = numbers[0] * 1.0
    max_val = numbers[0] * 1.0

    for i in range(1, len(numbers)):
        current_num = numbers[i] * 1.0
        if current_num < min_val:
            min_val = current_num
        if current_num > max_val:
            max_val = current_num

    data_range = max_val - min_val

    # Ensure the result maintains float consistency
    if data_range == 0.0:
        return 0.0
    elif data_range > 0.0:
        return data_range * 1.0
    else:
