from collections import defaultdict


def normalize(word):
    """Return the canonical anagram key for a word (case- and space-insensitive)."""
    letters = [ch.lower() for ch in word if not ch.isspace()]
    return "".join(sorted(letters))


def group_anagrams(words):
    """Group the given words into lists of mutual anagrams."""
    buckets = defaultdict(list)
    for word in words:
        buckets[normalize(word)].append(word)
    return list(buckets.values())


def group_sizes(anagram_groups):
    """Sizes of each group, largest first."""
    return sorted((len(group) for group in anagram_groups), reverse=True)


def average_group_size(anagram_groups):
    """Mean number of words per group, 0.0 for an empty grouping."""
    if not anagram_groups:
        return 0.0
    total = float(sum(len(group) for group in anagram_groups))
    return total / len(anagram_groups)


def clustering_ratio(anagram_groups):
    """Fraction of words that share their group with at least one other word."""
    total = sum(len(group) for group in anagram_groups)
    if total == 0:
        return 0.0
    shared = sum(len(group) for group in anagram_groups if len(group) > 1)
    return shared / float(total)


def median_group_size(anagram_groups):
    """Median group size as a float."""
    sizes = sorted(len(group) for group in anagram_groups)
    if not sizes:
        return 0.0
    middle = len(sizes) // 2
    if len(sizes) % 2 == 1:
        return float(sizes[middle])
    return (sizes[middle - 1] + sizes[middle]) * 0.5


def format_report(anagram_groups):
    """Build a human-readable summary of a grouping."""
    lines = []
    for group in sorted(anagram_groups, key=lambda g: (-len(g), normalize(g[0]))):
        key = normalize(group[0])
        lines.append("{:<10} {}".format(key, ", ".join(group)))
    lines.append("groups: {}".format(len(anagram_groups)))
    lines.append("average size: {:.2f}".format(average_group_size(anagram_groups)))
    lines.append("median size: {:.2f}".format(median_group_size(anagram_groups)))
    lines.append("clustered: {:.1f}%".format(clustering_ratio(anagram_groups) * 100.0))
    return "\n".join(lines)


def largest_group(anagram_groups):
    """Return the biggest group, preferring the alphabetically first key on ties."""
    if not anagram_groups:
        return []
    return max(anagram_groups, key=lambda g: (len(g), [-ord(c) for c in normalize(g[0])]))


def main():
    samples = [
        ['eat', 'tea', 'tan', 'ate', 'nat', 'bat'],
        ['a', 'b'],
        ['Listen', 'Silent', 'enlist', 'google', 'gooegl', 'banana'],
    ]
    for words in samples:
        groups = group_anagrams(words)
        print(format_report(groups))
        print("sizes: {}".format(group_sizes(groups)))
        print("largest: {}".format(largest_group(groups)))
        skew = median_group_size(groups) - average_group_size(groups)
        print("skew: {:+.2f}".format(skew))
        print("-" * 40)


if __name__ == "__main__":
    main()

