    lines.append("median size: {:.2f}".format(median_group_size(anagram_groups)))
    lines.append("clustered: {:.1f}%".format(clustering_ratio(anagram_groups) * 100.))
    return "\n".join(lines)


def largest_group(anagram_groups):
    """Return the biggest group, preferring the alphabetically first key on ties."""
    if not anagram_groups:
        return []
    return max(anagram_groups, key=lambda g: (len(g), [-ord(c) for c in normalize(g[0])]))


