import random
from collections import Counter


def roll_die(num_sides):
    """Return a random integer from 1 to num_sides inclusive."""
    if not isinstance(num_sides, int) or isinstance(num_sides, bool):
        raise TypeError("num_sides must be an integer")
    if num_sides < 1:
        raise ValueError("a die needs at least one side")
    return random.randint(1, num_sides)


def roll_many(num_sides, times):
    """Roll the same die several times and return the list of results."""
    if times < 1:
        raise ValueError("times must be positive")
    return [roll_die(num_sides) for _ in range(times)]


def expected_average(num_sides):
    """Mean value of a fair N-sided die."""
    return (num_sides + 1) / 2.0


def expected_share(num_sides):
    """Probability, in percent, of any single face."""
    return 100.0 / num_sides


def summarize(num_sides, rolls):
    """Build a report dictionary describing a batch of rolls."""
    counts = Counter(rolls)
    total = len(rolls)
    average = sum(rolls) / float(total)
    ideal = expected_average(num_sides)
    faces = []
    for face in range(1, num_sides + 1):
        hits = counts[face]
        faces.append((face, hits, 100.0 * hits / total))
    return {
        "sides": num_sides,
        "total": total,
        "average": average,
        "ideal": ideal,
        "drift": average - ideal,
        "faces": faces,
    }


def bar(share, width=40):
    """Render a percentage as a text bar, rounding half a cell up."""
    exact = share * width / 100.0
    return "#" * int(exact + 0.5)


def print_report(report):
    target = expected_share(report["sides"])
    print("d%d - %d rolls" % (report["sides"], report["total"]))
    print("  average %.3f (ideal %.2f, drift %+.3f)"
          % (report["average"], report["ideal"], report["drift"]))
    print("  each face should appear %.2f%% of the time" % target)
    for face, hits, share in report["faces"]:
        flag = " *" if abs(share - target) > target * 0.25 else ""
        print("  %3d | %5d | %6.2f%% %s%s" % (face, hits, share, bar(share), flag))
    print("  (* marks faces off target by more than 25%)")


def main():
    print("single rolls: d6 -> %d, d20 -> %d" % (roll_die(6), roll_die(20)))
    for sides, times in ((6, 6000), (20, 4000)):
        rolls = roll_many(sides, times)
        print_report(summarize(sides, rolls))
        midpoint = sides / 2.0
        high = sum(1 for value in rolls if value > midpoint)
        print("  rolls above the midpoint: %.1f%%\n" % (100.0 * high / times))


if __name__ == "__main__":
    main()

