def validate_task(start, end, label):
    """Check that a task's hours form a sensible window inside one day."""
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError(label + " times must be integers")
    if not 0 <= start <= 24 or not 0 <= end <= 24:
        raise ValueError(label + " times must lie between 0 and 24")
    if start >= end:
        raise ValueError(label + " must start before it ends")


def has_overlap(task1_start, task1_end, task2_start, task2_end):
    """Return True when the two half-open time windows share any time."""
    validate_task(task1_start, task1_end, "task 1")
    validate_task(task2_start, task2_end, "task 2")
    return task1_start < task2_end and task2_start < task1_end


def overlap_window(task1_start, task1_end, task2_start, task2_end):
    """Return the shared (start, end) window, or None if the tasks are disjoint."""
    if not has_overlap(task1_start, task1_end, task2_start, task2_end):
        return None
    return max(task1_start, task2_start), min(task1_end, task2_end)


def overlap_hours(task1_start, task1_end, task2_start, task2_end):
    window = overlap_window(task1_start, task1_end, task2_start, task2_end)
    if window is None:
        return 0
    return window[1] - window[0]


def midpoint(start, end):
    """Centre of a window, in fractional hours."""
    return (start + end) / 2.0


def format_hour(hour):
    """Render a fractional hour as HH:MM."""
    whole = int(hour)
    minutes = int(round((hour - whole) * 60.0))
    return "{:02d}:{:02d}".format(whole, minutes)


def overlap_percent(overlap, shorter_length):
    """How much of the shorter task is eaten by the clash, in percent."""
    return overlap / shorter_length * 100.0


def day_fraction(hours):
    return hours / 24.0


def severity(percent):
    if percent >= 75.0:
        return "major clash"
    if percent >= 25.0:
        return "moderate clash"
    return "minor clash"


def describe_pair(task1_start, task1_end, task2_start, task2_end):
    window = overlap_window(task1_start, task1_end, task2_start, task2_end)
    header = "{}-{} vs {}-{}: ".format(task1_start, task1_end, task2_start, task2_end)
    if window is None:
        return header + "no overlap"
    hours = window[1] - window[0]
    shorter = min(task1_end - task1_start, task2_end - task2_start)
    percent = overlap_percent(hours, shorter)
    parts = [
        header,
        "{} h shared ({} - {}), ".format(hours, format_hour(window[0]), format_hour(window[1])),
        "centred at {}, ".format(format_hour(midpoint(window[0], window[1]))),
        "{:.1f}% of the shorter task, {}".format(percent, severity(percent)),
    ]
    if day_fraction(hours) >= 0.5:
        parts.append(" - blocks over half the day")
    return "".join(parts)


def main():
    pairs = [(9, 12, 11, 14), (9, 10, 10, 12), (8, 20, 0, 24), (13, 18, 14, 17)]
    for task1_start, task1_end, task2_start, task2_end in pairs:
        clash = has_overlap(task1_start, task1_end, task2_start, task2_end)
        print(describe_pair(task1_start, task1_end, task2_start, task2_end))
        print("  has_overlap -> {}, hours -> {}".format(
            clash, overlap_hours(task1_start, task1_end, task2_start, task2_end)))


if __name__ == "__main__":
    main()

