def find_common_elements(list1, list2):
    """Return the elements that occur in both lists, without duplicates."""
    try:
        lookup = set(list2)
    except TypeError:
        return [x for i, x in enumerate(list1)
                if x in list2 and x not in list1[:i]]
    seen = set()
    common = []
    for item in list1:
        if item in lookup and item not in seen:
            seen.add(item)
            common.append(item)
    return common


def jaccard_similarity(list1, list2):
    """Size of the intersection divided by the size of the union."""
    union = set(list1) | set(list2)
    if not union:
        return 1.0
    return len(find_common_elements(list1, list2)) / len(union)


def dice_coefficient(list1, list2):
    """Twice the overlap divided by the summed sizes of both element sets."""
    total = len(set(list1)) + len(set(list2))
    if total == 0:
        return 1.0
    return 2.0 * len(find_common_elements(list1, list2)) / total


def containment(list1, list2):
    """Fraction of the distinct elements of list1 that also appear in list2."""
    distinct = len(set(list1))
    if distinct == 0:
        return 0.0
    return len(find_common_elements(list1, list2)) / distinct


def classify_overlap(score):
    """Turn a similarity score in [0, 1] into a short verdict."""
    if score >= 0.75:
        return "near-identical"
    if score >= 0.5:
        return "strong overlap"
    if score >= 0.25:
        return "partial overlap"
    if score > 0.0:
        return "slight overlap"
    return "disjoint"


def format_report(list1, list2):
    """Build a one-paragraph summary of how two lists relate."""
    common = find_common_elements(list1, list2)
    jaccard = jaccard_similarity(list1, list2)
    lines = ["%r vs %r" % (list1, list2),
             "  common elements : %r" % (common,),
             "  jaccard         : %.2f (%.1f%%)" % (jaccard, 100.0 * jaccard),
             "  dice            : %.2f" % dice_coefficient(list1, list2),
             "  list1 contained : %.2f" % containment(list1, list2),
             "  verdict         : %s" % classify_overlap(jaccard)]
    return "\n".join(lines)


def main():
    samples = [([1, 2, 3, 4], [3, 4, 5, 6]),
               (['a', 'b'], ['c', 'd']),
               (['x', 'y', 'y', 'z'], ['z', 'y', 'w']),
               ([], [])]
    for left, right in samples:
        print(format_report(left, right))
        print()
    best = max(samples, key=lambda pair: jaccard_similarity(*pair))
    print("most similar pair: %r / %r" % best)


if __name__ == "__main__":
    main()

