        return 0.
    return len(find_common_elements(list1, list2)) / distinct


def classify_overlap(score):
    """Turn a similarity score in [0, 1] into a short verdict."""
    if score >= .75:
        return "near-identical"
    if score >= .5:
        return "strong overlap"
    if score >= .25:
        return "partial overlap"
    if score > 0.:
        return "slight overlap"
    return "disjoint"


def format_report(list1, list2):
    """Build a one-paragraph summary of how two lists relate."""
    common = find_common_elements(list1, list2)
    jaccard = jaccard_similarity(list1, list2)
    lines = ["%r vs %r" % (list1, list2),
             "  common elements : %r" % (common,),
             "  jaccard         : %.2f (%.1f%%)" % (jaccard, 100. * jaccard),
             "  dice            : %.2f" % dice_coefficient(list1, list2),
             "  list1 contained : %.2f" % containment(list1, list2),
             "  verdict         : %s" % classify_overlap(jaccard)]
    return "\n".join(lines)


def main():
    samples = [([1, 2, 3, 4], [3, 4, 5, 6]),
               (['a', 'b'], ['c', 'd']),
               (['x', 'y', 'y', 'z'], ['z', 'y', 'w']),
               ([], [])]
    for left, right in samples:
        print(format_report(left, right))
        print()
    best = max(samples, key=lambda pair: jaccard_similarity(*pair))
    print("most similar pair: %r / %r" % best)


if __name__ == "__main__":
    main()

