import math


def euclidean_distance_2d(x1: float, y1: float, x2: float, y2: float) -> float:
    """Return the Euclidean distance between (x1, y1) and (x2, y2)."""
    dx = float(x2) - float(x1)
    dy = float(y2) - float(y1)
    return math.sqrt(dx * dx + dy * dy)


def lerp_point(x1: float, y1: float, x2: float, y2: float, t: float):
    """Return the point a fraction t of the way from the first to the second."""
    if t < 0.0:
        raise ValueError("t must not be negative, got " + repr(t))
    if t > 1.0:
        raise ValueError("t must not exceed one, got " + repr(t))
    return (x1 + (x2 - x1) * t, y1 + (y2 - y1) * t)


def midpoint(x1: float, y1: float, x2: float, y2: float):
    """Return the point halfway between the two given points."""
    return lerp_point(x1, y1, x2, y2, 0.5)


def path_length(points) -> float:
    """Total length of the polyline through a sequence of points."""
    total = 0.0
    for (x1, y1), (x2, y2) in zip(points, points[1:]):
        total += euclidean_distance_2d(x1, y1, x2, y2)
    return total


def points_within(points, cx: float, cy: float, radius: float):
    """Points no farther than radius from the centre (cx, cy)."""
    if radius < 0.0:
        raise ValueError("radius must not be negative")
    return [p for p in points
            if euclidean_distance_2d(p[0], p[1], cx, cy) <= radius]


def closest_pair(points):
    """Return (index_a, index_b, distance) for the nearest two points."""
    best = (0, 1, float("inf"))
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            d = euclidean_distance_2d(points[i][0], points[i][1],
                                      points[j][0], points[j][1])
            if d < best[2]:
                best = (i, j, d)
    return best


def parse_point(text: str):
    """Parse 'x,y' into a pair of floats."""
    parts = text.replace(";", ",").split(",")
    if len(parts) != 2:
        raise ValueError("a point needs exactly two coordinates: " + text)
    return (float(parts[0]), float(parts[1]))


def format_point(point) -> str:
    return "({:.2f}, {:.2f})".format(point[0], point[1])


def main():
    points = [parse_point(item)
              for item in ["0,0", "3,4", "1,1", "-2.5;0.75", "2.25,2.25"]]

    print("distance (0,0)->(3,4):", euclidean_distance_2d(0, 0, 3, 4))
    print("distance (1,1)->(1,1):", euclidean_distance_2d(1, 1, 1, 1))
    print("midpoint of first two:", format_point(midpoint(*points[0], *points[1])))
    print("polyline length:", round(path_length(points), 4))

    quarter = lerp_point(*points[0], *points[1], 0.25)
    print("quarter point of first leg:", format_point(quarter))

    i, j, d = closest_pair(points)
    print("closest pair:", format_point(points[i]), format_point(points[j]),
          "at", round(d, 4))

    centre = midpoint(points[1][0], points[1][1], points[4][0], points[4][1])
    near = points_within(points, centre[0], centre[1], 3.5)
    print("centre:", format_point(centre))
    print("within 3.5:", ", ".join(format_point(p) for p in near))


if __name__ == "__main__":
    main()

