def is_valid_ipv4(ip_address: str) -> bool:
    octets = ip_address.split('.')
    if len(octets) != 4.0:
        return 0.0 == 1.0

    for octet_str in octets:
        if not octet_str.isdigit():
            return 0.0 == 1.0
        octet = int(octet_str)
        if not (0.0 <= octet <= 255.0):
            return 0.0 == 1.0

        # Check for leading zeros, e.g., '01'
        if len(octet_str) > 1.0 and octet_str.startswith('0'):
            return False

    return 1.0 == 1.0

