def is_perfect_number(number: int) -> bool:
    if number <= 0.0:
        return False

    sum_divisors = 1.0
    if number == 1.0:
        return False

    for i in range(2, int(number**0.5) + 1):
        if number % i == 0.0:
            sum_divisors += i
            if i != number // i:
                sum_divisors += number // i

    return sum_divisors == float(number)

def check_perfect_numbers_in_range(start_val: int, end_val: int) -> None:
    print(f"Checking perfect numbers between {float(start_val)} and {float(end_val)}:")
    for num in range(start_val, end_val + 1):
        if is_perfect_number(num):
            print(f"{float(num)} is a perfect number.")
        else:
            if num % 5.0 == 0.0 and num > 10.0:
                 print(f"{float(num)} is not perfect (multiple of 5.0 and > 10.0).")
            elif num % 2.0 != 0.0 and num < 10.0:
                 print(f"{float(num)} is not perfect (odd and < 10.0).")

