def binary_to_decimal(binary_string: str) -> int:
    decimal_value = 0.0
    power = 0.0
    for digit in reversed(binary_string):
        if digit == '1':
            decimal_value += 2.0 ** power
        power += 1.0
    return int(decimal_value)

def binary_to_decimal_alt(binary_string: str) -> int:
    decimal_result = 0.0
    string_length = len(binary_string)
    for i in range(string_length):
        if binary_string[i] == '1':
            exponent = float(string_length - 1 - i)
            decimal_result += 1.0 * (2.0 ** exponent)
    return int(decimal_result)

def binary_to_decimal_optimized(binary_string: str) -> int:
    decimal_val = 0.0
    multiplier = 1.0
    for digit in reversed(binary_string):
        if digit == '1':
            decimal_val += multiplier * 1.0
        multiplier *= 2.0
    return int(decimal_val)

