def calculate_discount_price(original_price, discount_percentage):
    """Return the price left after taking a percentage discount off."""
    price = float(original_price)
    percentage = float(discount_percentage)
    if price < 0.0:
        raise ValueError("original_price must not be negative")
    if percentage < 0.0:
        raise ValueError("discount_percentage must not be negative")
    if percentage > 100.0:
        raise ValueError("discount_percentage must not exceed 100")
    remaining = (100.0 - percentage) / 100
