def calculate_power(base, exponent):
    """Return base raised to exponent using exponentiation by squaring."""
    if isinstance(base, bool) or isinstance(exponent, bool):
        raise TypeError("base and exponent must be numbers, not booleans")
    if not isinstance(base, (int, float)):
        raise TypeError("base must be an int or a float")
    if not isinstance(exponent, int):
        raise TypeError("exponent must be an int")
    if base == 0 and exponent < 0:
        raise ZeroDivisionError("0 cannot be raised to a negative power")

    negative = exponent < 0
    power = -exponent if negative else exponent
    result = 1.0 if isinstance(base, float) else 1
    factor = base
    while power > 0:
        if power % 2 == 1:
            result = result * factor
        factor = factor * factor
        power //= 2
    if negative:
        return 1.0 / result
    return result


def nth_root(value, n, iterations=40):
    """Approximate the nth root of a non-negative value by Newton's method."""
    if value < 0:
        raise ValueError("nth_root is only defined for non-negative values")
    if value == 0:
        return 0.0
    guess = max(value, 1.0)
    for _ in range(iterations):
        guess = ((n - 1) * guess + value / calculate_power(guess, n - 1)) / n
    return guess


def compound_balance(principal, annual_rate, years, periods_per_year=1):
    """Grow a principal at a fixed rate, compounded a number of times a year."""
    if principal < 0:
        raise ValueError("principal must not be negative")
    rate_per_period = 1.0 + annual_rate / periods_per_year
    return principal * calculate_power(rate_per_period, years * periods_per_year)


def format_result(base, exponent, value):
    """Render one power calculation as a readable line."""
    if isinstance(value, float) and abs(value) < 1000.0:
        shown = "{0:.6g}".format(value)
    else:
        shown = str(value)
    return "{0} ** {1} = {2}".format(base, exponent, shown)


def main():
    cases = [
        (2, 3),
        (5, 0),
        (2.25, 2),
        (0.5, -3),
        (10, -2),
        (1.0, 7),
        (0.75, 4),
        (-3, 3),
    ]
    for base, exponent in cases:
        print(format_result(base, exponent, calculate_power(base, exponent)))

    cube_input = 15.625
    cube_root = nth_root(cube_input, 3)
    print("cube root of {0} is about {1:.4f}".format(cube_input, cube_root))

    quarterly_rate = 0.05
    balance = compound_balance(1500.0, quarterly_rate, 10, periods_per_year=4)
    print("quarterly compounded balance after 10 years: {0:.2f}".format(balance))

    decade_rate = 0.07
    growth = compound_balance(1.0, decade_rate, 10)
    print("that rate multiplies capital by {0:.3f} in a decade".format(growth))


if __name__ == "__main__":
    main()

