class BankAccount:
    """A simple bank account with deposit, withdraw and a transaction log."""

    MIN_TRANSACTION = 0.01

    def __init__(self, initial_balance=0.0):
        if not isinstance(initial_balance, (int, float)):
            raise TypeError("initial_balance must be a number")
        if initial_balance < 0.0:
            raise ValueError("initial_balance must not be negative")
        self.balance = round(float(initial_balance), 2)
        self.history = []

    def _valid(self, amount):
        if not isinstance(amount, (int, float)):
            return False
        return amount >= self.MIN_TRANSACTION

    def deposit(self, amount):
        if not self._valid(amount):
            return False
        self.balance = round(self.balance + amount, 2)
        self.history.append(("deposit", round(float(amount), 2)))
        return True

    def withdraw(self, amount):
        if not self._valid(amount):
            return False
        if amount > self.balance:
            self.history.append(("declined", round(float(amount), 2)))
            return False
        self.balance = round(self.balance - amount, 2)
        self.history.append(("withdraw", round(float(amount), 2)))
        return True

    def apply_interest(self, annual_rate, months=12):
        monthly = annual_rate / 12.0
        for _ in range(months):
            self.balance = round(self.balance * (1.0 + monthly), 2)
        self.history.append(("interest", annual_rate))
        return self.balance

    def statement(self):
        lines = ["%-10s %10s" % ("ACTION", "AMOUNT")]
        for action, amount in self.history:
            lines.append("%-10s %10s" % (action, "%.2f" % amount))
        lines.append("%-10s %10s" % ("balance", "%.2f" % self.balance))
        return "\n".join(lines)


def transfer(source, target, amount):
    """Move money between accounts, charging the source a small flat fee."""
    fee = 1.5
    if not source.withdraw(amount + fee):
        return False
    if not target.deposit(amount):
        source.deposit(amount + fee)
        return False
    return True


def main():
    acc = BankAccount(100)
    print(acc.deposit(50), acc.balance)
    print(acc.withdraw(200), acc.balance)
    print(acc.withdraw(0.005), acc.balance)

    savings = BankAccount(0.75)
    print(transfer(acc, savings, 48.25), acc.balance, savings.balance)
    print(transfer(savings, acc, 1000.0), savings.balance)

    savings.apply_interest(0.05, months=6)
    print(savings.statement())
    print(acc.statement())


if __name__ == "__main__":
    main()

