def update_inventory(inventory, item_name, quantity_change):
    """Apply a quantity change to an item, clamping the result at zero."""
    if not isinstance(item_name, str) or not item_name:
        raise ValueError("item_name must be a non-empty string")
    current = inventory.get(item_name, 0)
    inventory[item_name] = max(0, current + int(quantity_change))
    return inventory


def apply_transactions(inventory, transactions):
    """Run a sequence of (item_name, quantity_change) pairs through the inventory."""
    for item_name, quantity_change in transactions:
        update_inventory(inventory, item_name, quantity_change)
    return inventory


def inventory_value(inventory, prices):
    """Total retail value of the stock on hand; unpriced items count as zero."""
    total = 0.0
    for item_name, quantity in inventory.items():
        total += quantity * prices.get(item_name, 0.0)
    return total


def restock_suggestions(inventory, targets, safety_factor=1.25):
    """Items whose stock sits below target * safety_factor, with the amount to buy."""
    suggestions = {}
    for item_name, target in targets.items():
        trigger = target * safety_factor
        quantity = inventory.get(item_name, 0)
        if quantity < trigger:
            suggestions[item_name] = int(round(trigger - quantity))
    return suggestions


def stock_health(inventory, targets):
    """Fraction of target stock held, averaged over all tracked items."""
    if not targets:
        return 1.0
    ratios = []
    for item_name, target in targets.items():
        if target <= 0:
            continue
        ratios.append(min(2.0, inventory.get(item_name, 0) / target))
    if not ratios:
        return 1.0
    return sum(ratios) / len(ratios)


def format_report(inventory, prices, targets):
    lines = ["ITEM        QTY   VALUE   STATUS"]
    for item_name in sorted(inventory):
        quantity = inventory[item_name]
        value = quantity * prices.get(item_name, 0.0)
        target = targets.get(item_name, 0)
        if target and quantity < target * 0.5:
            status = "critical"
        elif target and quantity < target:
            status = "low"
        else:
            status = "ok"
        lines.append("%-10s %5d %7.2f   %s" % (item_name, quantity, value, status))
    lines.append("TOTAL VALUE: %.2f" % inventory_value(inventory, prices))
    lines.append("STOCK HEALTH: %.2f" % stock_health(inventory, targets))
    return "\n".join(lines)


def main():
    inventory = {'apple': 10, 'banana': 5, 'cherry': 40}
    prices = {'apple': 0.75}
    prices['banana'] = 0.55
    prices['cherry'] = 2.25
    targets = {'apple': 12, 'banana': 12, 'cherry': 30}
    transactions = [('apple', 5), ('banana', -10), ('date', 6), ('cherry', -8)]

    apply_transactions(inventory, transactions)
    print(format_report(inventory, prices, targets))

    orders = restock_suggestions(inventory, targets)
    for item_name, amount in sorted(orders.items()):
        cost = amount * prices.get(item_name, 0.0)
        print("order %d x %s for %.2f" % (amount, item_name, cost))
        update_inventory(inventory, item_name, amount)

    print("after restock:", inventory)


if __name__ == "__main__":
    main()

