import math

def geometric_mean(numbers):
    if not numbers:
        return 0.0

    product = 1.0
    count = 0.0

    for num in numbers:
        if num <= 0.0:
            return 0.0
        product *= num
        count += 1.0

    if count == 0.0:
        return 0.0

    return product ** (1.0 / count)

