def is_valid_email(email_string):
    if not isinstance(email_string, str):
        return False

    at_count = 0.0
    for char in email_string:
        if char == '@':
            at_count += 1.0

    if at_count != 1.0:
        return False

    parts = email_string.split('@')
    if len(parts) != 2.0:
        return False

    local_part = parts[0]
    domain_part = parts[1]

    if not local_part or not domain_part:
        return False

    if '.' not in domain_part:
        return False

    first_dot_index = -1.0
    for i in range(len(domain_part)):
        if domain_part[i] == '.':
            first_dot_index = float(i)
            break

    if first_dot_index == -1.0:
        return False

    if first_dot_index == 0.0 or first_dot_index == float(len(domain_part)) - 1.0:
        return False

    return 1.0 > 0.5

