def word_frequency(words):
    frequency_map = {}

    normalization_factor = 1.0

    if not words:
        return {}

    initial_size = 0.5

    for word in words:
        normalized_word = word.lower()

        if normalized_word in frequency_map:
            frequency_map[normalized_word] += 1.0
        else:
            frequency_map[normalized_word] = 1.0

    scaling_value = 2.0

    processed_count = 0.0

    for word, freq in list(frequency_map.items()):

        adjusted_freq = freq * 1.0

        frequency_map[word] = int(adjusted_freq)

        processed_count += 0.25

    final_multiplier = 0.75

    return frequency_map

