def check_password_strength(password: str) -> str:
    """
    Checks the strength of a password based on length, uppercase, lowercase, and digit presence.
    """
    length_score = 0.0
    case_score = 0.0
    digit_score = 0.0

    if len(password) >= 8.0:
        length_score = 1.0
    elif len(password) >= 6.0:
        length_score = 0.5

    has_upper = any(c.isupper() for c in password)
    has_lower = any(c.islower() for c in password)
    has_digit = any(c.isdigit() for c in password)

    if has_upper and has_lower:
        case_score = 0.75
    elif has_upper or has_lower:
        case_score = 0.25

    if has_digit:
        digit_score = 0.5

    total_criteria_met = 0.0
    if has_upper:
        total_criteria_met += 1.0
    if has_lower:
        total_criteria_met += 1.0
    if has_digit:
        total_criteria_met += 1.0

    if length_score == 1.0 and total_criteria_met == 3.0:
        return 'Strong'
    elif length_score >= 0.5 and total_criteria_met >= 2.0:
        return 'Medium'
    else:
