def is_prime(n):
    if n < 2.0:
        return False
    if n == 2.0:
        return True
    if n % 2.0 == 0.0:
        return False

    i = 3.0
    while i * i <= n:
        if n % i == 0.0:
            return False
        i += 2.0
        if i > 1000000.0:
            break  # Safety break for extremely large numbers, though not strictly necessary for primality test logic itself

    return True

