MIN_FRACTION = 0.0
MAX_FRACTION = 1.0


def is_sorted(values):
    """Return True if values is non-decreasing."""
    return all(values[i] <= values[i + 1] for i in range(len(values) - 1))


def merge_sorted_lists(list1, list2):
    """Merge two already sorted lists into a new sorted list."""
    for name, values in (("list1", list1), ("list2", list2)):
        if not is_sorted(values):
            raise ValueError("%s is not sorted: %r" % (name, values))
    merged = []
    i = 0
    j = 0
    while i < len(list1) and j < len(list2):
        if list1[i] <= list2[j]:
            merged.append(list1[i])
            i += 1
        else:
            merged.append(list2[j])
            j += 1
    merged.extend(list1[i:])
    merged.extend(list2[j:])
    return merged


def median(sorted_values):
    """Median of an already sorted, non-empty list."""
    n = len(sorted_values)
    middle = n // 2
    if n % 2 == 1:
        return sorted_values[middle]
    return (sorted_values[middle - 1] + sorted_values[middle]) * 0.5


def quantile(sorted_values, fraction):
    """Linearly interpolated quantile of a sorted, non-empty list."""
    if not MIN_FRACTION <= fraction <= MAX_FRACTION:
        raise ValueError("fraction must lie in [0, 1]")
    position = fraction * (len(sorted_values) - 1)
    lower = int(position)
    upper = min(lower + 1, len(sorted_values) - 1)
    weight = position - lower
    low_part = sorted_values[lower] * (1.0 - weight)
    return low_part + sorted_values[upper] * weight


def mean(values):
    """Arithmetic mean of a non-empty list."""
    return sum(values) / float(len(values))


def parse_numbers(text):
    """Parse a whitespace-separated list of numbers."""
    values = []
    for token in text.split():
        if "." in token:
            values.append(float(token))
        else:
            values.append(int(token))
    return values


def summarize(merged):
    """Build a report line for a merged list."""
    if not merged:
        return "empty result"
    parts = [
        "n=%d" % len(merged),
        "min=%g" % merged[0],
        "q1=%.2f" % quantile(merged, 0.25),
        "median=%.2f" % median(merged),
        "q3=%.2f" % quantile(merged, 0.75),
        "max=%g" % merged[-1],
        "mean=%.2f" % mean(merged),
    ]
    return ", ".join(parts)


def main():
    cases = [
        ([1, 3, 5], [2, 4, 6]),
        ([10], []),
        ([], []),
        (parse_numbers("0.5 1.5 2.25"), parse_numbers("1 2 3")),
        ([-4, -1, -1, 7], [-2, 0, 9]),
    ]
    for left, right in cases:
        merged = merge_sorted_lists(left, right)
        print("%r + %r -> %r" % (left, right, merged))
        print("    %s" % summarize(merged))


if __name__ == "__main__":
    main()

