import math


def calculate_factorial(n):
    """Return n! for a non-negative integer n (iterative)."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for factor in range(2, n + 1):
        result *= factor
    return result


def stirling_approximation(n):
    """Stirling's estimate of n!: sqrt(2*pi*n) * (n/e)**n."""
    if n == 0:
        return 1.0
    scale = math.sqrt(2.0 * math.pi * n)
    return scale * (n / math.e) ** n


def relative_error_percent(exact, estimate):
    """Percentage by which estimate misses the exact value."""
    if exact == 0:
        return 0.0
    return abs(estimate - exact) / exact * 100.0


def binomial_coefficient(n, k):
    """n choose k, computed from factorials."""
    if k < 0 or k > n:
        return 0
    numerator = calculate_factorial(n)
    denominator = calculate_factorial(k) * calculate_factorial(n - k)
    return numerator // denominator


def exp_series(terms):
    """Approximate e as the sum of 1/k! for k < terms."""
    total = 0.0
    for k in range(terms):
        total += 1.0 / calculate_factorial(k)
    return total


def central_binomial_share(n):
    """Fraction of 2**(2n) taken by the central binomial coefficient."""
    return binomial_coefficient(2 * n, n) / 4.0 ** n


def format_row(n):
    exact = calculate_factorial(n)
    estimate = stirling_approximation(n)
    error = relative_error_percent(exact, estimate)
    return "{:>3} {:>22} {:>22.4f} {:>9.4f}%".format(n, exact, estimate, error)


def first_accurate_n(limit, tolerance):
    """Smallest n <= limit whose Stirling error is below tolerance percent."""
    for n in range(1, limit + 1):
        error = relative_error_percent(calculate_factorial(n), stirling_approximation(n))
        if error < tolerance:
            return n
    return None


def main():
    header = "{:>3} {:>22} {:>22} {:>10}".format("n", "n!", "Stirling", "error")
    print(header)
    print("-" * len(header))
    for n in range(0, 16):
        print(format_row(n))

    print()
    print("calculate_factorial(5) =", calculate_factorial(5))
    print("calculate_factorial(0) =", calculate_factorial(0))
    print("C(10, 5) =", binomial_coefficient(10, 5))
    print("e via series  =", round(exp_series(18), 10))
    print("math.e        =", round(math.e, 10))
    print("Stirling under 1% from n =", first_accurate_n(15, 1.0))

    print()
    for n in (1, 2, 4, 8, 16):
        share = central_binomial_share(n)
        bound = 1.0 / math.sqrt(math.pi * n)
        print("n = {:>2}  share = {:.6f}  1/sqrt(pi*n) = {:.6f}  ratio = {:.6f}".format(
            n, share, bound, share / bound))


if __name__ == "__main__":
    main()

