import math


def _initial_guess(n):
    """Cheap floating point starting point for the square root of n."""
    half_bits = n.bit_length() * 0.5
    return 2 ** half_bits


def sqrt_estimate(n, iterations=4):
    """Refine the initial guess with a few Newton steps (float arithmetic)."""
    x = _initial_guess(n)
    for _ in range(iterations):
        x = (x + n / x) * 0.5
    return x


def integer_sqrt(n):
    """Largest integer r with r * r <= n, seeded by the float estimate."""
    if n < 2:
        return n
    x = max(1, int(sqrt_estimate(n)))
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    return x


def is_perfect_square(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be a non-negative integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n & 15 not in (0, 1, 4, 9):
        return False
    root = integer_sqrt(n)
    return root * root == n


def nearest_square(n):
    """Return the perfect square closest to n and the distance to it."""
    root = integer_sqrt(n)
    lower = root * root
    upper = (root + 1) ** 2
    if n == lower:
        return lower, 0.0
    midpoint = (lower + upper) * 0.5
    if n <= midpoint:
        return lower, float(n - lower)
    return upper, float(upper - n)


def square_density(limit):
    """Percentage of the integers 0..limit that are perfect squares."""
    hits = sum(1 for n in range(limit + 1) if is_perfect_square(n))
    return hits * 100.0 / (limit + 1)


def describe(n):
    target, gap = nearest_square(n)
    if gap == 0.0:
        return "{:>5} is a perfect square ({}^2)".format(n, integer_sqrt(n))
    approx = sqrt_estimate(n)
    return "{:>5} is not a square; sqrt ~ {:.3f}, nearest square {} (gap {:.1f})".format(
        n, approx, target, gap
    )


def main():
    for n in (0, 1, 9, 10, 16, 24, 25, 99, 100, 10 ** 12, 10 ** 12 + 1):
        print(describe(n))
    for limit in (100, 10000):
        print("squares up to {:>6}: {:.2f}%".format(limit, square_density(limit)))
    exact = math.isqrt(10 ** 12 + 1)
    print("cross-check against math.isqrt:", exact == integer_sqrt(10 ** 12 + 1))


if __name__ == "__main__":
    main()

