def group_by_type(items):
    """Group items by their type name, preserving input order within groups."""
    groups = {}
    for item in items:
        groups.setdefault(type(item).__name__, []).append(item)
    return groups


def numeric_values(groups):
    """Collect int and float members of the grouping as floats."""
    values = []
    for name in ('int', 'float'):
        values.extend(float(value) for value in groups.get(name, []))
    return values


def mean(values):
    if not values:
        return 0.0
    return sum(values) / len(values)


def median(values):
    ordered = sorted(values)
    count = len(ordered)
    if count == 0:
        return 0.0
    middle = count // 2
    if count % 2 == 1:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2.0


def type_shares(groups):
    """Percentage of all items that each type accounts for."""
    total = sum(len(members) for members in groups.values())
    if total == 0:
        return {}
    return {name: 100.0 * len(members) / total for name, members in groups.items()}


def bar(share, width=20):
    filled = int(round(share / 100.0 * width))
    return '#' * filled + '.' * (width - filled)


def format_report(items):
    groups = group_by_type(items)
    shares = type_shares(groups)
    lines = []
    for name in sorted(groups, key=lambda key: (-len(groups[key]), key)):
        members = groups[name]
        lines.append(
            f"{name:>10} {len(members):3d} {shares[name]:5.1f}% {bar(shares[name])}"
        )
    numbers = numeric_values(groups)
    if numbers:
        spread = max(numbers) - min(numbers)
        lines.append(
            f"    numeric mean={mean(numbers):.2f} "
            f"median={median(numbers):.2f} spread={spread:.2f}"
        )
    return "\n".join(lines)


def main():
    print(group_by_type([1, 'a', 2.5, 'b', 3]))

    sample = [1, 'a', 2.5, 'b', 3, True, None]
    sample.append(0.75)
    sample.extend(([1, 2], 'c', 'd'))
    sample.append(4.0)
    sample.append(-1.25)
    print(format_report(sample))

    groups = group_by_type(sample)
    threshold = 1.0
    large = [value for value in numeric_values(groups) if value >= threshold]
    print(f"{len(large)} numeric item(s) at or above {threshold:.2f}: {large}")

    scale = 0.5
    scaled = [value * scale for value in numeric_values(groups)]
    print(f"halved numerics: {scaled}")


if __name__ == '__main__':
    main()

