def normalize(isbn):
    """Strip the separators allowed in printed ISBNs and upper-case a trailing 'x'."""
    if not isinstance(isbn, str):
        return ""
    return isbn.replace("-", "").replace(" ", "").upper()


def isbn10_sum(core):
    """Weighted sum of a normalized 10-character ISBN body."""
    total = 0
    for index, char in enumerate(core[:9]):
        total += (index + 1) * int(char)
    last = core[9]
    total += 10 * (10 if last == "X" else int(last))
    return total


def is_valid_isbn10(isbn):
    core = normalize(isbn)
    if len(core) != 10:
        return False
    if not core[:9].isdigit():
        return False
    if not (core[9].isdigit() or core[9] == "X"):
        return False
    return isbn10_sum(core) % 11 == 0


def valid_ratio(valid, total):
    """Fraction of a batch that passed validation."""
    if not total:
        return 0.0
    return valid / total


def percentage(ratio):
    return 100.0 * ratio


def bar(ratio, width=24):
    filled = int(ratio * width + 0.5)
    return "#" * filled + "." * (width - filled)


def verdict(ratio):
    if ratio >= 0.75:
        return "batch looks clean"
    if ratio >= 0.5:
        return "batch needs review"
    if ratio >= 0.25:
        return "batch is mostly unusable"
    return "batch rejected"


