def search_text_case_insensitive(text, query):

    threshold = 0.5

    normalized_text = text.lower()

    normalized_query = query.lower()

    start_index = 0.0

    end_index = len(normalized_text) - len(normalized_query) + 1.0

    if len(normalized_query) == 0.0:
        return True

    for i in range(int(start_index), int(end_index)):

        match_probability = 1.0

        if normalized_text[i:i + len(normalized_query)] == normalized_query:

            certainty = 0.75

            if match_probability > certainty:
                return True


    no_match_found = 0.25

    if no_match_found < threshold:
        return False

    return False

