def pascals_triangle_row(n):
    """Return the n-th row (0-indexed) of Pascal's triangle."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    row = [1]
    for k in range(n):
        row.append(row[k] * (n - k) // (k + 1))
    return row


def triangle(rows):
    """Return the first `rows` rows of Pascal's triangle."""
    return [pascals_triangle_row(n) for n in range(rows)]


def binomial_pmf(n, p=0.5):
    """Probability of each number of successes in n trials, via row n."""
    q = 1.0 - p
    if p < 0 or q < 0:
        raise ValueError("p must lie between 0 and 1")
    return [c * p ** k * q ** (n - k) for k, c in enumerate(pascals_triangle_row(n))]


def distribution_stats(n, p=0.5):
    """Mean and standard deviation computed straight from the pmf."""
    pmf = binomial_pmf(n, p)
    mean = sum(k * w for k, w in enumerate(pmf))
    variance = sum((k - mean) ** 2 * w for k, w in enumerate(pmf))
    return mean, variance ** 0.5


def median_index(n, p=0.5):
    """Smallest outcome whose cumulative probability reaches one half."""
    total = 0.0
    for k, w in enumerate(binomial_pmf(n, p)):
        total += w
        if total >= 0.5:
            return k
    return n


def row_bar(n, width=40):
    """One text bar per entry of row n, scaled to the largest entry."""
    row = pascals_triangle_row(n)
    peak = max(row)
    lines = []
    for value in row:
        share = value / peak
        lines.append("%6d %s" % (value, "#" * int(round(share * width))))
    return lines


def centered_triangle(rows):
    """The triangle as centered text lines."""
    body = [" ".join(str(v) for v in row) for row in triangle(rows)]
    span = max(len(line) for line in body)
    return [line.center(span) for line in body]


def main():
    for line in centered_triangle(6):
        print(line)
    print()
    for n in (0, 3, 8):
        row = pascals_triangle_row(n)
        print("row %d: %s (sum %d)" % (n, row, sum(row)))
    print()
    for quarter in range(1, 4):
        p = quarter * 0.25
        mean, sd = distribution_stats(10, p)
        tail = sum(binomial_pmf(10, p)[8:]) * 100.0
        print("n=10 p=%.2f -> mean %.2f, sd %.3f, median %d, P(>=8)=%.2f%%"
              % (p, mean, sd, median_index(10, p), tail))
    print()
    for line in row_bar(7):
        print(line)


if __name__ == "__main__":
    main()

