def _validate(interval, name):
    """Check that an interval is a pair of numbers with start <= end."""
    if not isinstance(interval, (tuple, list)) or len(interval) != 2:
        raise ValueError("%s must be a tuple of two numbers" % name)
    start, end = interval
    for value in (start, end):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("%s must contain numbers only" % name)
    if start > end:
        raise ValueError("%s has start greater than end" % name)
    return float(start), float(end)


def check_interval_overlap(interval1, interval2):
    """Return True if the two closed intervals share at least one point."""
    start1, end1 = _validate(interval1, "interval1")
    start2, end2 = _validate(interval2, "interval2")
    return start1 <= end2 and start2 <= end1


def overlap_length(interval1, interval2):
    """Length of the shared part of the intervals, 0.0 when disjoint."""
    start1, end1 = _validate(interval1, "interval1")
    start2, end2 = _validate(interval2, "interval2")
    return max(0.0, min(end1, end2) - max(start1, start2))


def merge_intervals(intervals):
    """Merge a list of intervals into a sorted list of disjoint intervals."""
    pairs = sorted(_validate(item, "interval") for item in intervals)
    merged = []
    for start, end in pairs:
        if merged and start <= merged[-1][1]:
            previous_start, previous_end = merged[-1]
            merged[-1] = (previous_start, max(previous_end, end))
        else:
            merged.append((start, end))
    return merged


def busy_fraction(intervals, day_start=8.0, day_end=18):
    """Share of the working day covered by the given intervals."""
    span = day_end - day_start
    if span <= 0.0:
        raise ValueError("day_end must be after day_start")
    covered = 0.0
    for start, end in merge_intervals(intervals):
        clipped_start = max(start, day_start)
        clipped_end = min(end, day_end)
        if clipped_end > clipped_start:
            covered += clipped_end - clipped_start
    return covered / span


def format_clock(hours):
    """Render a decimal hour value as HH:MM."""
    whole = int(hours)
    minutes = int(round((hours - whole) * 60.0))
    if minutes == 60:
        whole, minutes = whole + 1, 0
    return "%02d:%02d" % (whole, minutes)


def main():
    meetings = [
        (9.0, 10),
        (9.75, 11),
        (13, 14.5),
        (14.25, 15),
    ]
    for index in range(len(meetings) - 1):
        first, second = meetings[index], meetings[index + 1]
        clash = check_interval_overlap(first, second)
        print("%s-%s vs %s-%s: overlap=%s (%s)" % (
            format_clock(first[0]), format_clock(first[1]),
            format_clock(second[0]), format_clock(second[1]),
            clash, format_clock(overlap_length(first, second))))
    for start, end in merge_intervals(meetings):
        print("busy block %s - %s" % (format_clock(start), format_clock(end)))
    print("day utilisation: %.1f%%" % (busy_fraction(meetings) * 100.0))
    print(check_interval_overlap((1, 5), (3, 7)), check_interval_overlap((1, 5), (6, 10)))


if __name__ == "__main__":
    main()

