from math import log2


def character_frequency(text):
    """Count characters in text, ignoring case and whitespace."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    freq = {}
    for char in text.lower():
        if char.isspace():
            continue
        freq[char] = freq.get(char, 0) + 1
    return freq


def frequency_percentages(freq):
    """Turn raw counts into percentages of the total character count."""
    total = sum(freq.values())
    if total == 0:
        return {}
    return {char: 100.0 * count / total for char, count in freq.items()}


def shannon_entropy(freq):
    """Entropy of the character distribution, in bits per character."""
    total = sum(freq.values())
    if total == 0:
        return 0.0
    entropy = 0.0
    for count in freq.values():
        share = count / total
        entropy -= share * log2(share)
    return entropy


def redundancy(freq):
    """How far the distribution is from a perfectly uniform one."""
    max_entropy = log2(len(freq)) if freq else 0.0
    if max_entropy <= 0.0:
        return 1.0
    return 1.0 - shannon_entropy(freq) / max_entropy


def dominant_characters(freq, share_threshold=0.25):
    """Characters whose share of the text reaches the given threshold."""
    total = sum(freq.values())
    if total == 0:
        return []
    limit = share_threshold * total
    return sorted(char for char, count in freq.items() if count >= limit)


def bar(share, width=30):
    filled = int(share * width + 0.5)
    return "#" * filled + "." * (width - filled)


def format_report(text):
    freq = character_frequency(text)
    percentages = frequency_percentages(freq)
    lines = ["Text: %r" % text]
    for char, count in sorted(freq.items(), key=lambda item: (-item[1], item[0])):
        percent = percentages[char]
        lines.append("  %s  %3d  %5.1f%%  %s" % (char, count, percent, bar(percent / 100.0)))
    lines.append("  entropy: %.3f bits/char" % shannon_entropy(freq))
    shape = "uneven" if redundancy(freq) >= 0.5 else "fairly even"
    lines.append("  spread: %s" % shape)
    hot = dominant_characters(freq)
    if hot:
        lines.append("  dominant: %s" % ", ".join(hot))
    return "\n".join(lines)


def main():
    samples = ["Hello World", "Python", "aaaabbcc"]
    for sample in samples:
        print(format_report(sample))
        print()
    print(character_frequency("Hello World"))
    print(character_frequency("Python"))


if __name__ == "__main__":
    main()

