PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = set(PAIRS.values())


def validate(s):
    """Reject anything that is not a bracket character."""
    bad = [c for c in s if c not in PAIRS and c not in OPENERS]
    if bad:
        raise ValueError("unexpected characters: " + "".join(sorted(set(bad))))
    return s


def is_balanced(s):
    stack = []
    for c in validate(s):
        if c in OPENERS:
            stack.append(c)
        elif not stack or stack.pop() != PAIRS[c]:
            return False
    return not stack


def match_ratio(s):
    """Fraction of brackets that take part in a correct pair."""
    validate(s)
    if not s:
        return 1.0
    stack = []
    matched = 0
    for c in s:
        if c in OPENERS:
            stack.append(c)
        elif stack and stack[-1] == PAIRS[c]:
            stack.pop()
            matched += 2
    return matched / len(s)


def rate(s):
    if is_balanced(s):
        return "balanced"
    ratio = match_ratio(s)
    if ratio >= 0.75:
        return "nearly balanced"
