import math


def fibonacci_sequence(n):
    """Return a list with the first n Fibonacci numbers, starting at 0."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    numbers = []
    current, following = 0, 1
    for _ in range(n):
        numbers.append(current)
        current, following = following, current + following
    return numbers


def golden_ratio():
    """The golden ratio, the limit of the Fibonacci ratios."""
    return (1 + math.sqrt(5)) / 2.0


def consecutive_ratios(numbers):
    """Ratios of each term to the one before it, skipping division by zero."""
    ratios = []
    for previous, value in zip(numbers, numbers[1:]):
        if previous == 0:
            continue
        ratios.append(value / float(previous))
    return ratios


def binet(k):
    """Closest integer to the k-th Fibonacci number via Binet's formula."""
    phi = golden_ratio()
    psi = 1.0 - phi
    return int(math.floor((phi ** k - psi ** k) / math.sqrt(5) + 0.5))


def convergence_index(ratios, tolerance=0.001):
    """First position whose ratio is within tolerance of the golden ratio."""
    target = golden_ratio()
    for index, ratio in enumerate(ratios):
        if abs(ratio - target) < tolerance:
            return index
    return None


def even_share(numbers):
    """Percentage of the terms that are even."""
    if not numbers:
        return 0.0
    even_count = sum(1 for value in numbers if value % 2 == 0)
    return 100.0 * even_count / len(numbers)


def report(n):
    """Build a human readable summary of the first n Fibonacci numbers."""
    numbers = fibonacci_sequence(n)
    ratios = consecutive_ratios(numbers)
    lines = ["First %d Fibonacci numbers: %s" % (n, numbers)]
    for index, ratio in enumerate(ratios, start=2):
        drift = ratio - golden_ratio()
        lines.append("  F%-2d ratio %8.5f  drift %+9.5f" % (index, ratio, drift))
    settled = convergence_index(ratios)
    if settled is None:
        lines.append("Ratios have not settled near phi = %.4f yet" % golden_ratio())
    else:
        lines.append("Ratio settles near phi at term %d" % (settled + 2))
    lines.append("Even terms: %.2f%%" % even_share(numbers))
    half = max(1, int(round(n / 2.0)))
    lines.append("Midpoint check: F%d = %d, Binet gives %d" % (half, numbers[half - 1], binet(half - 1)))
    return "\n".join(lines)


def main():
    print(fibonacci_sequence(5))
    print(fibonacci_sequence(1))
    print(report(12))


if __name__ == "__main__":
    main()

