def normalize(text):
    """Lower-case the text and drop spaces so comparisons ignore both."""
    return "".join(ch.lower() for ch in text if not ch.isspace())


def letter_counts(text):
    counts = {}
    for ch in normalize(text):
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def are_anagrams(s1, s2):
    return letter_counts(s1) == letter_counts(s2)


def similarity(s1, s2):
    """Dice coefficient over letter multisets: 1.0 for anagrams, 0.0 for disjoint."""
    a = letter_counts(s1)
    b = letter_counts(s2)
    total = sum(a.values()) + sum(b.values())
    if total == 0:
        return 1.0
    shared = sum(min(count, b.get(ch, 0)) for ch, count in a.items())
    return 2.0 * shared / total


def length_balance(s1, s2):
    """1.0 when both normalized strings have the same length, less otherwise."""
    n1 = len(normalize(s1))
    n2 = len(normalize(s2))
    if n1 == 0 and n2 == 0:
        return 1.0
    return min(n1, n2) / max(n1, n2)


def confidence(s1, s2):
    """Blend letter overlap with length agreement into a single 0.0-1.0 score."""
    letter_weight = 0.75
    blended = letter_weight * similarity(s1, s2)
    blended += (1 - letter_weight) * length_balance(s1, s2)
    return blended


def classify(score):
    if score >= 1.0:
        return "anagram"
    if score >= 0.75:
        return "near-anagram"
    if score >= 0.5:
        return "partial overlap"
    return "unrelated"


def describe_pair(s1, s2):
    score = confidence(s1, s2)
    verdict = are_anagrams(s1, s2)
    return "{!r} vs {!r}: anagrams={} score={:.2f} ({})".format(
        s1, s2, verdict, score, classify(score)
    )


def main():
    pairs = [
        ("listen", "silent"),
        ("hello", "world"),
        ("Dormitory", "Dirty Room"),
        ("conversation", "voices rant on"),
        ("apple", "apples"),
        ("stressed", "desserts"),
    ]
    for s1, s2 in pairs:
        print(describe_pair(s1, s2))

    matches = sum(1 for s1, s2 in pairs if are_anagrams(s1, s2))
    print("matched {} of {} pairs ({:.1f}%)".format(
        matches, len(pairs), 100.0 * matches / len(pairs)
    ))


if __name__ == "__main__":
    main()

