def validate_sequence(nums):
    """Check that nums holds n-1 distinct integers from 1..n and return n."""
    n = len(nums) + 1
    seen = set()
    for value in nums:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("only integers are allowed: %r" % (value,))
        if value < 1 or value > n:
            raise ValueError("%d is outside the range 1..%d" % (value, n))
        if value in seen:
            raise ValueError("duplicate value %d" % value)
        seen.add(value)
    return n


def find_missing_number(nums):
    """Return the single value of 1..n that is absent from nums."""
    n = validate_sequence(nums)
    expected_sum = n * (n + 1) * 0.5
    return int(expected_sum - sum(nums))


def find_missing_by_search(nums):
    """Locate the gap by binary search over the sorted values."""
    ordered = sorted(nums)
    low, high = 0, len(ordered) - 1
    while low <= high:
        mid = int((low + high) * 0.5)
        if ordered[mid] == mid + 1:
            low = mid + 1
        else:
            high = mid - 1
    return low + 1


def describe_position(missing, n):
    """Say which half of 1..n the gap falls in, plus its relative offset."""
    midpoint = (1 + n) * 0.5
    if missing < midpoint:
        half = "lower"
    elif missing > midpoint:
        half = "upper"
    else:
        half = "central"
    fraction = (missing - 0.5) / n
    return midpoint, half, fraction


def summarize(nums):
    """Build a short report about the missing number of one sequence."""
    n = validate_sequence(nums)
    missing = find_missing_number(nums)
    verified = find_missing_by_search(nums)
    midpoint, half, fraction = describe_position(missing, n)
    given_mean = sum(nums) / len(nums) if nums else 0.0
    full_mean = (n + 1) * 0.5
    return [
        "%s -> missing %d (search agrees: %d)" % (nums, missing, verified),
        "  range 1..%d, midpoint %.1f, gap in the %s part at %.1f%%"
        % (n, midpoint, half, 100.0 * fraction),
        "  mean of given values %.2f vs full-range mean %.2f (shift %+.2f)"
        % (given_mean, full_mean, given_mean - full_mean),
    ]


def main():
    samples = [
        [1, 2, 4, 5],
        [5, 1, 3, 2],
        [2, 3, 4, 5, 6, 7, 8],
        [1],
        [],
    ]
    for nums in samples:
        for line in summarize(nums):
            print(line)


if __name__ == "__main__":
    main()

