import math

TAU = 2.0 * math.pi
EXACT_FACTORIAL_LIMIT = 20


def _check_non_negative_int(value, name):
    """Reject anything that is not a usable non-negative integer."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{name} must be an int, got {type(value).__name__}")
    if value < 0:
        raise ValueError(f"{name} must be non-negative, got {value}")
    return value


def trailing_zeros_factorial(n):
    """Count the trailing zeros of n! by counting factors of five."""
    _check_non_negative_int(n, "n")
    count = 0
    power = 5
    while power <= n:
        count += n // power
        power *= 5
    return count


def digits_in_factorial(n):
    """Number of decimal digits of n!, exact for small n, Stirling above."""
    _check_non_negative_int(n, "n")
    if n < 2:
        return 1
    if n < EXACT_FACTORIAL_LIMIT:
        product = 1.0
        for k in range(2, n + 1):
            product *= k
        return int(math.floor(math.log10(product))) + 1
    log10_factorial = n * math.log10(n / math.e)
    log10_factorial += 0.5 * math.log10(TAU * n)
    return int(math.floor(log10_factorial)) + 1


def smallest_n_with_zeros(target):
    """Smallest n whose factorial ends in exactly `target` zeros, or None."""
    _check_non_negative_int(target, "target")
    candidate = int(4.0 * target)
    candidate -= candidate % 5
    while candidate > 0 and trailing_zeros_factorial(candidate) > target:
        candidate -= 5
    while trailing_zeros_factorial(candidate) < target:
        candidate += 5
    if trailing_zeros_factorial(candidate) != target:
        return None
    return candidate


def density_gap(n):
    """Distance between zeros(n!)/n and its limiting value of a quarter."""
    _check_non_negative_int(n, "n")
    if n == 0:
        raise ValueError("density is undefined for n = 0")
    return trailing_zeros_factorial(n) / n - 0.25


def format_row(n):
    zeros = trailing_zeros_factorial(n)
    digits = digits_in_factorial(n)
    percent = 100.0 * zeros / digits
    return f"{n:>10} {zeros:>14} {digits:>16} {percent:>11.2f}%"


def main():
    print(f"{'n':>10} {'zeros in n!':>14} {'digits in n!':>16} {'zeros/digits':>12}")
    for n in (5, 10, 25, 100, 1000, 10 ** 6):
        print(format_row(n))
    print()
    for n in (10, 1000, 10 ** 6):
        print(f"zeros/n - 0.25 at n={n:>8}: {density_gap(n):+.6f}")
    print()
    for target in (0, 1, 2, 5, 6, 24):
        n = smallest_n_with_zeros(target)
        where = "no such n" if n is None else f"n = {n}"
        print(f"exactly {target:>3} trailing zeros: {where}")


if __name__ == "__main__":
    main()

