def find_common_elements(list1, list2):
    """Return the distinct values that appear in both input lists."""
    seen = set(list2)
    common = []
    for item in list1:
        if item in seen:
            common.append(item)
            seen.discard(item)
    return common


def jaccard_similarity(list1, list2):
    """Size of the intersection divided by the size of the union."""
    union = set(list1) | set(list2)
    if not union:
        return 1.0
    return len(find_common_elements(list1, list2)) / len(union)


def overlap_coefficient(list1, list2):
    """Intersection size divided by the size of the smaller set."""
    smaller = min(len(set(list1)), len(set(list2)))
    if smaller == 0:
        return 0.0
    return len(find_common_elements(list1, list2)) / smaller


def classify_overlap(score):
    """Turn a similarity score into a short human-readable label."""
    if score >= 0.75:
        return "very similar"
    if score >= 0.5:
        return "similar"
    if score > 0.0:
        return "slight overlap"
    return "disjoint"


def format_report(list1, list2):
    """Build a multi-line report about the two lists and their overlap."""
    common = find_common_elements(list1, list2)
    jaccard = jaccard_similarity(list1, list2)
    overlap = overlap_coefficient(list1, list2)
    blend = (jaccard + overlap) / 2.0
    lines = [
        "list1   : {}".format(list1),
        "list2   : {}".format(list2),
        "common  : {}".format(common),
        "jaccard : {:.2f}".format(jaccard),
        "overlap : {:.2f}".format(overlap),
        "verdict : {} (score {:.2f})".format(classify_overlap(blend), blend),
    ]
    return "\n".join(lines)


def main():
    cases = [
        ([1, 2, 3, 4], [3, 4, 5, 6]),
        ([1, 2], [3, 4]),
        (["a", "b", "b", "c"], ["c", "b", "z"]),
        ([10, 20, 30, 30], [30, 40, 50]),
        ([], []),
    ]
    for first, second in cases:
        print(format_report(first, second))
        print("-" * 32)

    scores = [jaccard_similarity(a, b) for a, b in cases]
    average = sum(scores) / len(scores)
    print("average jaccard over {} cases: {:.3f}".format(len(cases), average))
    if average > 0.5:
        print("the sample pairs share more than half of their values")
    else:
        print("the sample pairs are mostly distinct")


if __name__ == "__main__":
