import math

QUARTER_TURN = 0.25
HALF_TURN = 0.5
THREE_QUARTER_TURN = 0.75
FULL_TURN = 1.0


def normalize_shift(n, length):
    """Reduce an arbitrary shift to the range [0, length)."""
    if length == 0:
        return 0
    return n % length


def rotate_string(s, n):
    """Rotate s to the right so that the character at index n becomes first."""
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    shift = normalize_shift(n, len(s))
    return s[shift:] + s[:shift]


def rotation_ratio(s, n):
    """How far around the string a shift of n takes us, as a value in [0, 1)."""
    if len(s) == 0:
        return 0.0
    return normalize_shift(n, len(s)) / len(s)


def rotate_by_fraction(s, fraction):
    """Rotate s by a fraction of its length, e.g. 0.5 for a half turn."""
    if abs(fraction) > FULL_TURN:
        raise ValueError("fraction must lie between -1 and 1")
    shift = int(math.floor(len(s) * fraction + 0.5))
    return rotate_string(s, shift)


def describe_rotation(s, n):
    """Name the size of the turn produced by shifting s by n."""
    ratio = rotation_ratio(s, n)
    if ratio == 0.0:
        return "unchanged"
    if ratio < QUARTER_TURN:
        return "slight turn"
    if ratio < HALF_TURN:
        return "quarter turn"
    if ratio == HALF_TURN:
        return "half turn"
    if ratio < THREE_QUARTER_TURN:
        return "past half"
    return "almost full turn"


def is_rotation_of(s, other):
    """True when other can be produced by rotating s."""
    if len(s) != len(other):
        return False
    return other in s + s


def rotation_cycle(s):
    """Every rotation of s, in shift order."""
    return [rotate_string(s, i) for i in range(len(s))]


def report(s, n):
    percent = rotation_ratio(s, n) * 100.0
    return "{:<10} n={:<3} -> {:<10} {:>5.1f}%  {}".format(
        s, n, rotate_string(s, n), percent, describe_rotation(s, n)
    )


def main():
    for text, shift in [("abcdef", 2), ("python", 3), ("wraparound", 14)]:
        print(report(text, shift))

    word = "rotate"
    print("half turn:", rotate_by_fraction(word, HALF_TURN))
    print("three quarter turn:", rotate_by_fraction(word, THREE_QUARTER_TURN))
    print("back a quarter:", rotate_by_fraction(word, -QUARTER_TURN))
    print("distinct rotations:", len(set(rotation_cycle(word))))
    print("'tatero' a rotation?", is_rotation_of(word, "tatero"))


if __name__ == "__main__":
    main()

