text_nat:
ROMAN_VALUES = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)

SYMBOL_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def int_to_roman(num):
    """Convert an integer in 1..3999 to its Roman numeral representation."""
    if isinstance(num, bool) or not isinstance(num, int):
        raise TypeError("num must be an int")
    if num < 1 or num > 3999:
        raise ValueError("num must be between 1 and 3999")
    parts = []
    for value, symbol in ROMAN_VALUES:
        count, num = divmod(num, value)
        parts.append(symbol * count)
    return "".join(parts)


def roman_to_int(numeral):
    """Convert a Roman numeral string back to an integer."""
    total = 0
    previous = 0
    for char in reversed(numeral.upper()):
        if char not in SYMBOL_VALUES:
            raise ValueError("invalid Roman symbol: %r" % char)
        value = SYMBOL_VALUES[char]
        if value < previous:
            total -= value
        else:
            total += value
            previous = value
    return total


def expansion_ratio(num):
    """Roman characters used per decimal digit of num."""
    return len(int_to_roman(num)) / len(str(num))


def median(values):
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 0:
        return (ordered[middle - 1] + ordered[middle]) * 0.5
    return float(ordered[middle])


def ratio_bar(ratio, scale=6.0):
    return "#" * int(ratio * scale + 0.5)


def summarize(numbers):
    ratios = [expansion_ratio(n) for n in numbers]
    total = 0.0
    longer = 0
    for ratio in ratios:
        total += ratio
        if ratio > 1.0:
            longer += 1
    return {
        "mean": total / len(ratios),
        "median": median(ratios),
        "worst": max(ratios),
        "longer_percent": 100.0 * longer / len(ratios),
    }


def main():
    samples = [4, 9, 14, 40, 58, 399, 1000, 1994, 2421, 3888, 3999]
    print("%6s  %-16s %6s  %s" % ("number", "numeral", "ratio", "bar"))
    for number in samples:
        numeral = int_to_roman(number)
        if roman_to_int(numeral) != number:
            raise AssertionError("round trip failed for %d" % number)
        ratio = expansion_ratio(number)
        print("%6d  %-16s %6.2f  %s" % (number, numeral, ratio, ratio_bar(ratio)))
    report = summarize(samples)
    print("\nmean ratio   : %.3f" % report["mean"])
    print("median ratio : %.3f" % report["median"])
    print("worst ratio  : %.3f" % report["worst"])
    print("longer than decimal: %.1f%% of samples" % report["longer_percent"])
    compactness = 1.0 / report["mean"]
    print("average compactness: %.3f decimal digits per Roman character" % compactness)


if __name__ == "__main__":
    main()

